// ---------------------------------------------------------------------------
// Audio: all sound is synthesized with Web Audio. No external files.
// ---------------------------------------------------------------------------
const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.noiseBuffer = null;
    this.enabled = true;
    this.music = null;
    this.step = 0;
    this.nextTime = 0;
    this.timer = null;
    this.started = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? 0.85 : 0;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.16;
      this.musicGain.connect(this.master);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.6;
      this.sfxGain.connect(this.master);
      this.noiseBuffer = this._makeNoise();
      this.started = true;
      if (this.music) this._startScheduler();
    } catch {
      this.ctx = null;
    }
  }

  setEnabled(on) {
    this.enabled = on;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(on ? 0.85 : 0, this.ctx.currentTime, 0.03);
    if (!on) this._stopScheduler();
    else if (this.music) this._startScheduler();
  }

  setMusic(mode) {
    if (this.music === mode) return;
    this.music = mode;
    if (!this.ctx || !this.enabled) return;
    this._stopScheduler();
    if (mode) this._startScheduler();
  }

  _makeNoise() {
    const len = Math.floor(this.ctx.sampleRate * 1.5);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) * 0.995;
      data[i] = white * 0.7 + last * 2.2;
    }
    return buf;
  }

  // ---- low-level helpers -------------------------------------------------
  _env(gain, time, attack, hold, release, peak = 1) {
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), time + attack);
    gain.gain.setValueAtTime(Math.max(0.0002, peak), time + attack + hold);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + attack + hold + release);
  }

  tone({ freq = 440, type = 'sine', dur = 0.16, gain = 0.25, slide = 1, delay = 0, dest = null, attack = 0.006 }) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide !== 1) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(dest || this.sfxGain);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noise({ dur = 0.2, gain = 0.2, freq = 900, q = 0.8, type = 'bandpass', delay = 0, slide = null, dest = null }) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filt = this.ctx.createBiquadFilter();
    filt.type = type;
    filt.frequency.setValueAtTime(freq, t);
    if (slide) filt.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t + dur);
    filt.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filt);
    filt.connect(g);
    g.connect(dest || this.sfxGain);
    src.start(t);
    src.stop(t + dur + 0.03);
  }

  // ---- game sounds -------------------------------------------------------
  hit(damage = 8, heavy = false) {
    if (!this.ctx) return;
    const d = Math.min(1, 0.4 + damage / 26);
    this.tone({ freq: heavy ? 130 : 190, slide: heavy ? 0.42 : 0.55, type: 'triangle', dur: 0.16 + d * 0.12, gain: 0.34 * d });
    this.noise({ dur: 0.12 + d * 0.1, gain: 0.27 * d, freq: heavy ? 700 : 1400, q: 0.7, slide: heavy ? 160 : 420 });
    this.tone({ freq: heavy ? 60 : 90, slide: 0.5, type: 'sine', dur: 0.2, gain: 0.24 * d });
    if (heavy) this.noise({ dur: 0.45, gain: 0.14, freq: 2600, q: 0.5, type: 'highpass' });
  }
  whiff() { this.noise({ dur: 0.1, gain: 0.08, freq: 1200, slide: 3200, q: 1.4, type: 'bandpass' }); }
  shieldHit() {
    this.tone({ freq: 620, slide: 1.35, type: 'sine', dur: 0.18, gain: 0.22 });
    this.noise({ dur: 0.14, gain: 0.11, freq: 3200, q: 2, type: 'bandpass' });
  }
  shieldBreak() {
    this.tone({ freq: 900, slide: 0.25, type: 'sawtooth', dur: 0.5, gain: 0.2 });
    this.noise({ dur: 0.5, gain: 0.24, freq: 2400, slide: 300, q: 0.9 });
  }
  jump() { this.tone({ freq: 300, slide: 1.9, type: 'sine', dur: 0.12, gain: 0.12 }); }
  doubleJump() {
    this.tone({ freq: 460, slide: 1.8, type: 'triangle', dur: 0.18, gain: 0.14 });
    this.noise({ dur: 0.18, gain: 0.05, freq: 2600, slide: 5200, q: 1.6 });
  }
  land(force = 1) {
    this.noise({ dur: 0.14, gain: 0.11 * Math.min(1.6, force), freq: 320, slide: 100, type: 'lowpass' });
  }
  dodge() { this.noise({ dur: 0.16, gain: 0.1, freq: 900, slide: 2400, q: 1.2 }); }
  ko() {
    this.noise({ dur: 1.1, gain: 0.34, freq: 1200, slide: 70, q: 0.6, type: 'lowpass' });
    this.tone({ freq: 170, slide: 0.22, type: 'sawtooth', dur: 0.9, gain: 0.26 });
    this.tone({ freq: 70, slide: 0.3, type: 'sine', dur: 1.2, gain: 0.32 });
    this.noise({ dur: 1.4, gain: 0.1, freq: 2200, q: 0.4, delay: 0.12 });
    this.tone({ freq: 880, slide: 1.5, type: 'square', dur: 0.35, gain: 0.07, delay: 0.05 });
  }
  rise() {
    this.tone({ freq: 220, slide: 2.8, type: 'triangle', dur: 0.35, gain: 0.16 });
    this.noise({ dur: 0.35, gain: 0.1, freq: 800, slide: 3000, q: 1.1 });
  }
  projectile(kind) {
    if (kind === 'fireball') {
      this.noise({ dur: 0.3, gain: 0.16, freq: 900, slide: 240, q: 0.8 });
      this.tone({ freq: 330, slide: 0.7, type: 'sawtooth', dur: 0.2, gain: 0.08 });
    } else if (kind === 'bolt') {
      this.tone({ freq: 1400, slide: 0.32, type: 'square', dur: 0.2, gain: 0.1 });
      this.noise({ dur: 0.12, gain: 0.09, freq: 4200, q: 2 });
    } else if (kind === 'ice') {
      this.tone({ freq: 1100, slide: 1.5, type: 'sine', dur: 0.25, gain: 0.1 });
      this.tone({ freq: 1650, slide: 1.2, type: 'triangle', dur: 0.18, gain: 0.06 });
    } else if (kind === 'seed') {
      this.tone({ freq: 520, slide: 1.7, type: 'triangle', dur: 0.16, gain: 0.13 });
    }
  }
  counter() {
    this.tone({ freq: 760, slide: 1.4, type: 'square', dur: 0.22, gain: 0.12 });
    this.tone({ freq: 1520, slide: 1.2, type: 'sine', dur: 0.3, gain: 0.08 });
    this.noise({ dur: 0.25, gain: 0.12, freq: 1800, slide: 4200, q: 2 });
  }
  charge(level = 0) {
    this.tone({ freq: 200 + level * 6, slide: 1.25, type: 'triangle', dur: 0.1, gain: 0.045 + level * 0.001 });
  }
  beep(final = false) {
    this.tone({ freq: final ? 700 : 440, type: 'sine', dur: final ? 0.3 : 0.1, gain: 0.15 });
    this.tone({ freq: final ? 1050 : 660, type: 'triangle', dur: final ? 0.32 : 0.1, gain: 0.06 });
  }
  announce() {
    this.tone({ freq: 260, slide: 1.5, type: 'sawtooth', dur: 0.3, gain: 0.12 });
    this.tone({ freq: 520, slide: 1.4, type: 'square', dur: 0.35, gain: 0.05, delay: 0.03 });
  }
  click() {
    this.tone({ freq: 640, slide: 1.25, type: 'sine', dur: 0.06, gain: 0.08 });
  }
  hover() {
    this.tone({ freq: 880, type: 'sine', dur: 0.035, gain: 0.028 });
  }
  win() {
    [0, 4, 7, 12, 16].forEach((n, i) => {
      this.tone({ freq: NOTE(69 + n), type: 'triangle', dur: 0.35, gain: 0.15, delay: i * 0.1 });
      this.tone({ freq: NOTE(57 + n), type: 'sine', dur: 0.5, gain: 0.09, delay: i * 0.1 });
    });
  }

  // ---- music -------------------------------------------------------------
  _startScheduler() {
    if (this.timer) return;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.step = 0;
    this.timer = setInterval(() => this._pump(), 60);
  }
  _stopScheduler() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  _pump() {
    if (!this.ctx || !this.enabled || !this.music) return;
    const tempo = this.music === 'battle' ? 152 : 96;
    const stepDur = 60 / tempo / 2; // eighth notes
    while (this.nextTime < this.ctx.currentTime + 0.22) {
      this._playStep(this.step, this.nextTime, this.music, stepDur);
      this.nextTime += stepDur;
      this.step++;
      if (this.step > 9999) this.step = 0;
    }
  }

  _playStep(step, t, mode, dur) {
    if (!this.ctx) return;
    const dest = this.musicGain;
    const note = (freq, type, len, gain, when = t, slide = 1) => {
      const osc = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, when);
      if (slide !== 1) osc.frequency.exponentialRampToValueAtTime(freq * slide, when + len);
      g.gain.setValueAtTime(0.0001, when);
      g.gain.exponentialRampToValueAtTime(gain, when + 0.015);
      g.gain.exponentialRampToValueAtTime(0.0001, when + len);
      osc.connect(g); g.connect(dest); osc.start(when); osc.stop(when + len + 0.02);
    };
    const drum = (kind, when) => {
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer;
      const f = this.ctx.createBiquadFilter();
      const g = this.ctx.createGain();
      if (kind === 'kick') {
        f.type = 'lowpass'; f.frequency.value = 180;
        g.gain.setValueAtTime(0.25, when); g.gain.exponentialRampToValueAtTime(0.0001, when + 0.13);
      } else if (kind === 'hat') {
        f.type = 'highpass'; f.frequency.value = 6500;
        g.gain.setValueAtTime(0.035, when); g.gain.exponentialRampToValueAtTime(0.0001, when + 0.04);
      } else {
        f.type = 'bandpass'; f.frequency.value = 1800; f.Q.value = 0.7;
        g.gain.setValueAtTime(0.1, when); g.gain.exponentialRampToValueAtTime(0.0001, when + 0.12);
      }
      src.connect(f); f.connect(g); g.connect(dest);
      src.start(when); src.stop(when + 0.16);
    };

    if (mode === 'menu') {
      const bar = Math.floor(step / 8) % 4;
      const roots = [45, 41, 48, 43]; // Am F C G
      const chords = [[69, 72, 76], [65, 69, 72], [72, 76, 79], [67, 71, 74]];
      if (step % 8 === 0) {
        note(NOTE(roots[bar] - 12), 'triangle', dur * 7.4, 0.075);
        note(NOTE(chords[bar][0] - 12), 'sine', dur * 7.4, 0.035);
      }
      if (step % 2 === 0) {
        const arp = chords[bar][(step / 2) % 3];
        note(NOTE(arp), 'sine', 0.55, 0.028);
        note(NOTE(arp + 12), 'triangle', 0.5, 0.011);
      }
      if (step % 16 === 0) note(NOTE(roots[bar] + 12), 'sine', 1.1, 0.045);
    } else {
      const bar = Math.floor(step / 8) % 4;
      const roots = [45, 45, 43, 41];
      const lead = [69, 72, 76, 74, 76, 79, 76, 72];
      const bassPattern = [0, 0, 12, 0, 0, 7, 0, 12];
      if (step % 8 === 0 || step % 8 === 4) drum('kick', t);
      if (step % 2 === 1) drum('hat', t);
      if (step % 8 === 3 || step % 8 === 7) drum('snare', t);
      const b = roots[bar] + bassPattern[step % 8];
      note(NOTE(b - 12), 'sawtooth', dur * 0.8, 0.07);
      if (step % 2 === 0) {
        const l = lead[(step + bar * 3) % lead.length];
        note(NOTE(l), 'square', dur * 0.65, 0.025);
        note(NOTE(l + 12), 'triangle', dur * 0.4, 0.012);
      }
      if (step % 8 === 0) note(NOTE(roots[bar] + 24), 'triangle', dur * 2.2, 0.02);
    }
  }
}

export const audio = new AudioEngine();

// ---------------------------------------------------------------------------
// Input — keyboard for up to four local players, plus automatic gamepads.
// ---------------------------------------------------------------------------
const P = (slot, ...actions) => [slot, actions];

const KEYMAP = {
  // P1 — left hand
  KeyA: P(0, 'left'), KeyD: P(0, 'right'), KeyW: P(0, 'up', 'jump'), KeyS: P(0, 'down'),
  KeyF: P(0, 'attack'), KeyG: P(0, 'special'), KeyH: P(0, 'shield'), ShiftLeft: P(0, 'dodge'),
  // P2 — arrows + punctuation
  ArrowLeft: P(1, 'left'), ArrowRight: P(1, 'right'), ArrowUp: P(1, 'up', 'jump'), ArrowDown: P(1, 'down'),
  Comma: P(1, 'attack'), Period: P(1, 'special'), Slash: P(1, 'shield'), Quote: P(1, 'dodge'),
  // P3 — right hand letters
  KeyJ: P(2, 'left'), KeyL: P(2, 'right'), KeyI: P(2, 'up', 'jump'), KeyK: P(2, 'down'),
  KeyU: P(2, 'attack'), KeyO: P(2, 'special'), KeyP: P(2, 'shield'), Semicolon: P(2, 'dodge'),
  // P4 — numpad
  Numpad4: P(3, 'left'), Numpad6: P(3, 'right'), Numpad8: P(3, 'up', 'jump'), Numpad5: P(3, 'down'),
  Numpad7: P(3, 'attack'), Numpad9: P(3, 'special'), Numpad0: P(3, 'shield'), Numpad1: P(3, 'dodge'),
};

const GAME_KEYS = new Set(Object.keys(KEYMAP));
const PREVENT = new Set([
  ...GAME_KEYS, 'Space', 'Escape', 'Enter', 'Backspace', 'Tab',
]);
const EMPTY = Object.freeze(new Set());

export class InputManager {
  constructor() {
    this.down = new Set();
    this.pending = [new Set(), new Set(), new Set(), new Set()];
    this.prev = [new Set(), new Set(), new Set(), new Set()];
    this.padPrev = [];
    this.padPausePrev = false;
    this.pads = [];
    this.keyboardEnabled = true;
    this.lastSource = null;
    this._onKeyDown = this._onKeyDown.bind(this);
    this._onKeyUp = this._onKeyUp.bind(this);
    this._onBlur = () => this.releaseAll();
  }

  attach() {
    window.addEventListener('keydown', this._onKeyDown, { passive: false });
    window.addEventListener('keyup', this._onKeyUp);
    window.addEventListener('blur', this._onBlur);
    window.addEventListener('gamepadconnected', (e) => {
      this.padPrev[e.gamepad.index] = [];
    });
  }

  _onKeyDown(e) {
    const target = e.target;
    if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const map = KEYMAP[e.code];
    if (PREVENT.has(e.code)) e.preventDefault();
    if (!map) return;
    if (e.repeat) return;
    const [slot, actions] = map;
    if (!this.keyboardEnabled) return;
    this.lastSource = `p${slot + 1}`;
    for (const action of actions) {
      this.down.add(`${slot}:${action}`);
      this.pending[slot].add(action);
    }
  }

  _onKeyUp(e) {
    const map = KEYMAP[e.code];
    if (!map) return;
    const [slot, actions] = map;
    for (const action of actions) this.down.delete(`${slot}:${action}`);
  }

  releaseAll() {
    this.down.clear();
    this.pending.forEach((s) => s.clear());
  }

  poll() {
    this.pads = navigator.getGamepads ? Array.from(navigator.getGamepads()).filter(Boolean) : [];
    return this.pads;
  }

  get padCount() { return this.pads.length; }

  stateFor(slot) {
    const held = new Set();
    const pressed = new Set();

    if (this.keyboardEnabled) {
      for (const action of ['left', 'right', 'up', 'down', 'attack', 'special', 'shield', 'dodge', 'jump']) {
        if (this.down.has(`${slot}:${action}`)) held.add(action);
      }
      for (const action of this.pending[slot]) {
        pressed.add(action);
        held.add(action);
      }
    }

    const pad = this.pads.find((p) => p.index === slot);
    if (pad) {
      const ax = pad.axes[0] || 0;
      const ay = pad.axes[1] || 0;
      const b = pad.buttons;
      const btn = (i) => (b[i] ? b[i].value > 0.25 || b[i].pressed : false);
      if (ax < -0.38 || btn(14)) held.add('left');
      if (ax > 0.38 || btn(15)) held.add('right');
      if (ay < -0.42 || btn(12)) held.add('up');
      if (ay > 0.42 || btn(13)) held.add('down');
      if (btn(0)) held.add('jump');
      if (btn(2)) held.add('attack');
      if (btn(1)) held.add('special');
      if (btn(5) || btn(7)) held.add('shield');
      if (btn(4) || btn(6)) held.add('dodge');
      const prev = this.padPrev[slot] || [];
      for (const [i, action] of [[0, 'jump'], [2, 'attack'], [1, 'special'], [5, 'shield'], [7, 'shield'], [4, 'dodge'], [6, 'dodge']]) {
        if (btn(i) && !prev.includes(i)) pressed.add(action);
      }
      if ((ax < -0.38 || btn(14)) && !(this.padPrevAxes?.[slot]?.left)) {
        // dpad/stick direction presses are held-only; attacks use direction held
      }
      this.padPrev[slot] = [0, 1, 2, 4, 5, 6, 7].filter((i) => btn(i));
    }

    for (const action of held) {
      if (!this.prev[slot].has(action)) pressed.add(action);
    }
    this.prev[slot] = new Set(held);
    this.pending[slot].clear();

    if (!pressed.size && !held.size) {
      // still return new sets; callers only read
    }
    return { held, pressed };
  }

  pausePressed() {
    const pad = this.pads.find((p) => p.buttons && p.buttons[9] && p.buttons[9].pressed);
    const now = Boolean(pad);
    const result = now && !this.padPausePrev;
    this.padPausePrev = now;
    return result;
  }

  connectedPads() {
    return this.pads.map((p) => ({ index: p.index, id: p.id }));
  }
}

export function emptyInput() {
  return { held: EMPTY, pressed: EMPTY };
}

export function makeInput(heldArr = [], pressedArr = []) {
  return { held: new Set(heldArr), pressed: new Set(pressedArr) };
}

// ---------------------------------------------------------------------------
// Fighter — platform physics, attacks, shielding, knockback and stocks.
// ---------------------------------------------------------------------------
import {
  BLAST, GRAVITY, MAX_FALL, MAX_CHARGE, CHAR_MAP, SLOT_COLORS, SLOT_NAMES,
} from './data.js';
import { audio } from './audio.js';

const DEG = Math.PI / 180;
const ACTIONS = ['left', 'right', 'up', 'down', 'jump', 'attack', 'special', 'shield', 'dodge'];

function has(set, action) { return Boolean(set && set.has(action)); }

export class Fighter {
  constructor(slot, charId, kind, difficulty, stage) {
    this.slot = slot;
    this.id = slot;
    this.charId = charId;
    this.char = CHAR_MAP[charId] || CHAR_MAP.blaze;
    this.kind = kind; // human | cpu
    this.difficulty = difficulty || 2;
    this.color = SLOT_COLORS[slot];
    this.tag = SLOT_NAMES[slot];
    this.stocks = 3;
    this.stage = stage;
    this.spawn = stage.spawns[slot] || stage.spawns[0];
    this.time = 0;
    this.stats = { kos: 0, falls: 0, dealt: 0, taken: 0 };
    this.reset(stage, 3);
  }

  reset(stage, stocks) {
    this.stage = stage;
    this.spawn = stage.spawns[this.slot] || stage.spawns[0];
    this.stocks = stocks;
    this.x = this.spawn.x;
    this.y = this.spawn.y;
    this.vx = 0;
    this.vy = 0;
    this.facing = this.spawn.x <= 0 ? 1 : -1;
    this.grounded = true;
    this.wasGrounded = true;
    this.jumpsLeft = 2;
    this.damage = 0;
    this.action = null;
    this.move = null;
    this.moveKey = null;
    this.attackFrame = 0;
    this.charge = 0;
    this.charging = false;
    this.chargeFx = 0;
    this.hitTargets = new Set();
    this.spawned = new Set();
    this.hitstun = 0;
    this.hitstop = 0;
    this.invincible = 0;
    this.helpless = false;
    this.shieldHP = 100;
    this.shieldstun = 0;
    this.shieldTimer = 0;
    this.shieldbroken = 0;
    this.dodgeTimer = 0;
    this.dodgeDuration = 0;
    this.dodgeIframes = 0;
    this.airDodgeUsed = false;
    this.fastfall = false;
    this.cutJump = false;
    this.floatTimer = 0;
    this.koTimer = 0;
    this.eliminated = false;
    this.hitFlash = 0;
    this.counterFlash = 0;
    this.respawnGlow = 0;
    this.lastHitBy = null;
    this.lastHitMove = null;
    this.trail = [];
    this.runPhase = 0;
    this.animTime = Math.random() * 100;
    this.tumble = false;
    this.jabWindow = 0;
    this.armor = false;
    this.crouching = false;
    this.landSquash = 0;
    this.dustTimer = 0;
    this.damageDealtThisLife = 0;
    this.stats = { kos: 0, falls: 0, dealt: 0, taken: 0 };
  }

  get alive() { return !this.eliminated && this.stocks > 0; }
  get isCPU() { return this.kind === 'cpu'; }
  get power() { return this.char.physics; }
  get name() { return this.char.name; }

  get invulnerable() {
    return this.invincible > 0
      || (this.action === 'dodge' && this.dodgeTimer <= this.dodgeIframes)
      || this.respawnGlow > 0;
  }

  isCountering() {
    if (this.action !== 'attack' || !this.move || !this.move.counter) return false;
    return this.attackFrame >= this.move.startup && this.attackFrame < this.move.startup + this.move.active;
  }

  hurtbox() {
    const h = this.char.hurt;
    const crouch = this.crouching && this.grounded ? 0.74 : 1;
    const height = h.h * crouch;
    return { x: this.x - h.w / 2, y: this.y - height, w: h.w, h: height };
  }

  hitboxWorld() {
    if (!this.move || !this.move.hitbox) return null;
    const hb = this.move.hitbox;
    return { x: this.x + hb.x * this.facing, y: this.y + hb.y, r: hb.r };
  }

  // -------------------------------------------------------------------------
  update(input, game) {
    this.time++;
    this.animTime++;
    if (this.hitFlash > 0) this.hitFlash--;
    if (this.counterFlash > 0) this.counterFlash--;
    if (this.invincible > 0) this.invincible--;
    if (this.respawnGlow > 0) this.respawnGlow--;
    if (this.landSquash > 0) this.landSquash--;
    if (this.hitstop > 0) { this.hitstop--; return; }
    if (this.eliminated) return;

    if (this.koTimer > 0) {
      this.koTimer--;
      if (this.koTimer === 0) this.respawn(game);
      return;
    }

    if (this.floatTimer > 0) this.floatTimer--;

    // Shield regeneration
    if (this.action !== 'shield' && this.shieldstun <= 0) {
      this.shieldHP = Math.min(100, this.shieldHP + (this.shieldbroken > 0 ? 0.05 : 0.22));
    }
    if (this.shieldstun > 0) this.shieldstun--;

    this.wasGrounded = this.grounded;

    if (this.action === 'shieldbreak') {
      this.shieldTimer--;
      this.crouching = false;
      this.applyPhysics(input, game);
      this.postPhysics(game);
      if (this.shieldTimer <= 0) {
        this.action = null;
        this.shieldbroken = 0;
        this.shieldHP = Math.max(30, this.shieldHP);
      }
      return;
    }

    if (this.hitstun > 0) {
      this.hitstun--;
      this.crouching = false;
      if (this.hitstun === 0) this.tumble = false;
      // small drift while in hitstun
      if (!this.grounded) {
        const dir = (has(input.held, 'right') ? 1 : 0) - (has(input.held, 'left') ? 1 : 0);
        this.vx += dir * 0.045;
      }
      this.applyPhysics(input, game);
      this.postPhysics(game);
      return;
    }

    if (this.action === 'attack') {
      this.crouching = false;
      this.updateAttack(input, game);
      this.applyPhysics(input, game);
      this.postPhysics(game);
      return;
    }

    if (this.action === 'dodge') {
      this.updateDodge(game);
      this.applyPhysics(input, game);
      this.postPhysics(game);
      return;
    }

    if (this.action === 'shield') {
      this.updateShield(input, game);
      this.crouching = false;
      this.applyPhysics(input, game);
      this.postPhysics(game);
      return;
    }

    this.handleFree(input, game);
    this.applyPhysics(input, game);
    this.postPhysics(game);
  }

  // -------------------------------------------------------------------------
  handleFree(input, game) {
    const p = this.power;
    const held = input.held;
    const pressed = input.pressed;
    const dirX = (has(held, 'right') ? 1 : 0) - (has(held, 'left') ? 1 : 0);
    const down = has(held, 'down');
    const up = has(held, 'up');

    this.crouching = this.grounded && down;

    if (this.helpless) {
      if (this.grounded) this.helpless = false;
      else {
        if (dirX) {
          this.vx += dirX * 0.16;
          this.vx = Math.max(-p.airSpeed * 0.8, Math.min(p.airSpeed * 0.8, this.vx));
        }
        return;
      }
    }

    // Shield / dodge
    if (has(pressed, 'dodge')) {
      this.startDodge(input, game);
      return;
    }
    if (has(pressed, 'shield')) {
      if (this.grounded) this.startShield(game);
      else this.startDodge(input, game, true);
      return;
    }

    // Attacks and specials come before jumping so Up+Attack does an up smash.
    if (has(pressed, 'attack')) {
      this.startAttack(input, game);
      return;
    }
    if (has(pressed, 'special')) {
      this.startSpecial(input, game);
      return;
    }

    if (has(pressed, 'jump') && this.jumpsLeft > 0 && !this.crouching) {
      this.jump(game);
      return;
    }

    // Movement
    if (this.grounded) {
      if (this.crouching) {
        this.vx *= 0.72;
      } else {
        const target = dirX * p.runSpeed;
        if (dirX) {
          this.facing = dirX;
          this.vx += (target - this.vx) * 0.34;
          this.runPhase += Math.abs(this.vx) * 0.09;
          this.dustTimer++;
          if (Math.abs(this.vx) > 4 && this.dustTimer % 9 === 0) {
            game.dust(this.x - this.facing * 10, this.y, this.facing, this.color);
          }
        } else {
          this.vx *= p.traction;
          if (Math.abs(this.vx) < 0.15) this.vx = 0;
        }
      }
    } else {
      if (dirX) {
        this.vx += dirX * p.airAccel;
        this.vx = Math.max(-p.airSpeed, Math.min(p.airSpeed, this.vx));
        this.facing = dirX;
      } else {
        this.vx *= 0.985;
      }
      // fast fall
      if (has(pressed, 'down') && this.vy > -3 && !this.fastfall) {
        this.vy = Math.max(this.vy, 12.5);
        this.fastfall = true;
        game.dust(this.x, this.y - 10, 0, '#ffffff', 3);
      }
    }
  }

  jump(game) {
    const first = this.grounded;
    const p = this.power;
    this.grounded = false;
    this.y -= 2;
    this.vy = -(first ? p.jump : p.doubleJump);
    this.jumpsLeft--;
    this.cutJump = false;
    this.crouching = false;
    this.fastfall = false;
    this.landSquash = 0;
    this.dodgeTimer = 0;
    audio.jump();
    if (!first) {
      audio.doubleJump();
      game.ring(this.x, this.y - 22, this.color, 26);
      game.burst(this.x, this.y - 14, this.color, 6, 3);
    } else {
      game.dust(this.x, this.y, 0, '#ffffff', 3);
    }
  }

  startShield(game) {
    this.action = 'shield';
    this.shieldTimer = 0;
    this.vx *= 0.4;
    game.ring(this.x, this.y - 40, '#45e3ff', 22);
    audio.click();
  }

  updateShield(input, game) {
    this.shieldTimer++;
    if (this.shieldstun > 0) return;
    this.shieldHP -= 0.36;
    if (this.shieldHP <= 0) { this.breakShield(game); return; }
    if (!has(input.held, 'shield')) {
      this.action = null;
      this.shieldTimer = 0;
      this.shieldstun = 4;
    }
  }

  breakShield(game) {
    this.shieldHP = 0;
    this.action = 'shieldbreak';
    this.shieldTimer = 95;
    this.shieldbroken = 60;
    this.vx = 0;
    game.burst(this.x, this.y - 45, '#8fe9ff', 18, 7);
    game.ring(this.x, this.y - 42, '#8fe9ff', 60);
    game.announce('SHIELD BREAK', this.tag, '#8fe9ff', 40);
    audio.shieldBreak();
    game.shake = Math.max(game.shake, 9);
  }

  startDodge(input, game, forceAir = false) {
    if (!this.grounded && this.airDodgeUsed) return;
    const dirX = (has(input.held, 'right') ? 1 : 0) - (has(input.held, 'left') ? 1 : 0);
    const dirY = (has(input.held, 'down') ? 1 : 0) - (has(input.held, 'up') ? 1 : 0);
    this.action = 'dodge';
    this.dodgeTimer = 0;
    this.dodgeDuration = this.grounded ? 19 : 24;
    this.dodgeIframes = this.grounded ? 12 : 14;
    this.charging = false;
    this.move = null;
    if (this.grounded) {
      if (dirX) {
        this.facing = dirX;
        this.vx = dirX * 7.2;
      } else {
        this.vx = 0;
      }
      this.vy = 0;
      game.dust(this.x, this.y, -this.facing, '#d9d4ee', 4);
    } else {
      this.airDodgeUsed = true;
      this.vx = dirX * 7.0;
      this.vy = dirY * 6.4;
      if (!dirX && !dirY) this.vy = -1.5;
      this.fastfall = false;
      game.ring(this.x, this.y - 40, '#ffffff', 28);
    }
    audio.dodge();
  }

  updateDodge(game) {
    this.dodgeTimer++;
    if (this.dodgeTimer <= this.dodgeIframes && this.dodgeTimer % 3 === 0) {
      game.trailGhost(this);
    }
    if (this.grounded) this.vx *= 0.9;
    if (this.dodgeTimer >= this.dodgeDuration) {
      this.action = null;
      this.dodgeTimer = 0;
      if (this.grounded) this.vx *= 0.3;
    }
  }

  startAttack(input, game) {
    if (this.helpless) return;
    const held = input.held;
    const dirX = (has(held, 'right') ? 1 : 0) - (has(held, 'left') ? 1 : 0);
    const up = has(held, 'up');
    const down = has(held, 'down');
    let key;
    if (!this.grounded) {
      if (up) key = 'uair';
      else if (down) key = 'dair';
      else if (dirX) key = 'fair';
      else key = 'nair';
    } else {
      if (up) key = 'up';
      else if (down) key = 'down';
      else if (dirX) key = 'side';
      else if (Math.abs(this.vx) > this.power.runSpeed * 0.82) key = 'dash';
      else key = 'jab';
    }
    if (dirX) this.facing = dirX;
    this.beginMove(key, input);
    audio.whiff();
    if (this.grounded) game.dust(this.x, this.y, this.facing, '#ffffff', 2);
  }

  startSpecial(input, game) {
    if (this.helpless) return;
    const held = input.held;
    const dirX = (has(held, 'right') ? 1 : 0) - (has(held, 'left') ? 1 : 0);
    const up = has(held, 'up');
    const down = has(held, 'down');
    let key;
    if (up) key = 'uspecial';
    else if (down) key = 'dspecial';
    else if (dirX) key = 'sspecial';
    else key = 'nspecial';
    if (dirX) this.facing = dirX;
    this.beginMove(key, input);
    if (key === 'dspecial') audio.counter();
  }

  beginMove(key, input) {
    const move = this.char.moves[key];
    if (!move) return;
    this.action = 'attack';
    this.moveKey = key;
    this.move = move;
    this.attackFrame = 0;
    this.charge = 0;
    this.charging = Boolean(move.chargeable && has(input.held, 'attack'));
    this.hitTargets = new Set();
    this.spawned = new Set();
    this.crouching = false;
    this.armor = Boolean(move.armor);
    this.tumble = false;
    if (move.lunge && !this.grounded) this.vx *= 0.4;
  }

  updateAttack(input, game) {
    const m = this.move;
    if (!m) { this.action = null; return; }

    if (this.charging) {
      if (this.charge < MAX_CHARGE) {
        this.charge++;
        this.chargeFx++;
        if (this.charge % 8 === 0) audio.charge(this.charge);
        if (this.charge % 2 === 0) game.chargeSpark(this);
      }
      if (!has(input.held, 'attack')) this.charging = false;
      else return; // hold the pose
    }

    this.attackFrame++;
    const f = this.attackFrame;

    if (m.recover && f === m.recover.frame) {
      this.vy = m.recover.vy;
      this.vx = m.recover.vx * this.facing;
      this.grounded = false;
      this.jumpsLeft = Math.min(this.jumpsLeft, 1);
      this.floatTimer = m.float || 0;
      this.fastfall = false;
      game.burst(this.x - this.facing * 6, this.y - 8, this.char.palette.glow, 10, 6);
      game.ring(this.x, this.y - 10, this.char.palette.glow, 40);
      audio.rise();
    }
    if (m.spawn) {
      for (const s of m.spawn) {
        if (s.frame === f && !this.spawned.has(s.frame)) {
          this.spawned.add(s.frame);
          game.spawnProjectile(this, s.projectile);
          audio.projectile(s.projectile.kind);
          game.burst(this.x + this.facing * 30, this.y - 62, this.char.palette.glow, 6, 4);
        }
      }
    }
    if (m.lunge && f === m.startup) {
      this.vx = m.lunge * this.facing;
      game.dust(this.x, this.y, -this.facing, '#ffffff', 5);
      if (m.trail) game.trailGhost(this);
    }

    // active window
    if (f >= m.startup && f < m.startup + m.active) {
      if (m.hitbox && m.damage > 0 && !m.counter) this.checkHits(game);
      if (m.trail && f % 2 === 0) game.trailGhost(this);
    }

    if (f >= m.startup + m.active + m.recovery) {
      this.endMove();
    }
  }

  endMove() {
    const m = this.move;
    this.action = null;
    this.move = null;
    this.moveKey = null;
    this.attackFrame = 0;
    this.charge = 0;
    this.charging = false;
    this.armor = false;
    if (m && m.helpless) this.helpless = true;
  }

  checkHits(game) {
    const hb = this.hitboxWorld();
    if (!hb) return;
    for (const other of game.fighters) {
      if (other === this || !other.alive || other.koTimer > 0) continue;
      if (this.hitTargets.has(other.slot)) continue;
      const box = other.hurtbox();
      if (circleRect(hb.x, hb.y, hb.r, box)) {
        this.hitTargets.add(other.slot);
        this.landHit(other, game);
      }
    }
  }

  landHit(victim, game) {
    const m = this.move;
    if (!m) return;
    const chargeMul = 1 + (this.charge / MAX_CHARGE) * 0.55;
    const dmg = m.damage * chargeMul;
    const res = victim.takeHit(m, this, chargeMul, game, { dir: this.facing });

    if (res === 'countered') {
      this.stats.dealt += 0;
      return;
    }
    if (res === 'hit' || res === 'shield') {
      this.stats.dealt += res === 'hit' ? dmg : 0;
      this.charge = 0;
      game.hitstop = Math.max(game.hitstop, res === 'hit' ? (m.hitstop || 3) : 2);
      if (res === 'hit') {
        game.onHit(this, victim, dmg);
      } else {
        game.onShieldHit(this, victim);
      }
    }
  }

  // -------------------------------------------------------------------------
  takeHit(move, attacker, chargeMul, game, opts = {}) {
    if (!this.alive || this.koTimer > 0) return 'whiff';
    if (this.invulnerable) {
      game.whiffSpark(this.x, this.y - 45);
      return 'whiff';
    }
    if (this.isCountering()) {
      this.counterSuccess(attacker, game);
      return 'countered';
    }

    const shieldBlocks = this.action === 'shield' && this.shieldHP > 0 && this.grounded;
    if (shieldBlocks) {
      const dmg = move.damage * chargeMul;
      this.shieldHP -= dmg * 1.45 + 3.5;
      this.shieldstun = Math.max(this.shieldstun, 5 + dmg * 0.45);
      this.vx += Math.sign(opts.dir || 1) * (1.1 + dmg * 0.05);
      if (this.shieldHP <= 0) this.breakShield(game);
      audio.shieldHit();
      return 'shield';
    }

    const dir = opts.dir || (attacker ? attacker.facing : 1);
    const dmg = Math.max(0.5, move.damage * chargeMul);
    this.damage = Math.min(999, this.damage + dmg);
    this.stats.taken += dmg;
    this.hitFlash = 9;
    this.counterFlash = 0;
    this.action = null;
    this.move = null;
    this.moveKey = null;
    this.attackFrame = 0;
    this.charging = false;
    this.charge = 0;
    this.armor = false;
    this.shieldstun = 0;
    this.crouching = false;
    this.lastHitBy = attacker ? attacker.slot : null;

    const weight = this.power.weight || 1;
    let power = (move.baseKB + move.growth * (this.damage / 100));
    power *= 1 / Math.pow(weight, 0.8);
    power *= 1 + (chargeMul - 1) * 0.9;
    power = Math.min(190, power);

    const speed = Math.min(31, power * 0.165);
    const rad = (move.angle || 35) * DEG;
    this.vx = Math.cos(rad) * speed * dir;
    this.vy = -Math.sin(rad) * speed;
    if (this.vy > -1.2 && Math.abs(this.vx) < 3) this.vy = -2.2;
    this.hitstun = Math.round(Math.max(10, Math.min(110, 6 + power * 0.7)));
    this.tumble = power > 68;
    this.grounded = false;
    this.fastfall = false;
    this.y -= 1.5;
    this.jumpsLeft = Math.min(this.jumpsLeft, 1);

    if (this.armorFlag) this.armorFlag = false;
    game.burst(this.x, this.y - 45, '#fff4d8', Math.min(18, 7 + dmg), 6);
    game.ring(this.x, this.y - 45, '#ffffff', 34);
    game.shake = Math.max(game.shake, Math.min(14, 2 + dmg * 0.45));
    if (dmg >= 15) game.screenFlash = Math.max(game.screenFlash, 0.28);
    audio.hit(dmg, dmg > 13);
    return 'hit';
  }

  counterSuccess(attacker, game) {
    this.counterFlash = 32;
    this.invincible = Math.max(this.invincible, 30);
    this.hitstop = Math.max(this.hitstop, 8);
    game.hitstop = Math.max(game.hitstop, 8);
    game.onCounter(this, attacker);
    audio.counter();
    if (attacker && attacker.alive) {
      const cm = {
        damage: this.move.damage + Math.min(8, attacker.damage * 0.05),
        baseKB: this.move.baseKB,
        growth: this.move.growth,
        angle: this.move.angle,
      };
      attacker.takeHit(cm, this, 1, game, { dir: this.facing });
      this.stats.dealt += cm.damage;
      game.announce('COUNTER', this.tag, this.char.palette.glow, 34);
    }
    // Skip the remainder of the counter window
    this.attackFrame = this.move ? this.move.startup + this.move.active : 0;
  }

  // -------------------------------------------------------------------------
  applyPhysics(input, game) {
    const p = this.power;
    const dirX = (has(input.held, 'right') ? 1 : 0) - (has(input.held, 'left') ? 1 : 0);

    if (this.grounded) {
      this.vy = 0;
      if (this.action === 'attack' && !this.charging) this.vx *= 0.93;
      if (this.action === 'attack' && this.charging) this.vx *= 0.8;
      if (this.action === 'shield') this.vx *= 0.75;
      if (this.action === 'shieldbreak') this.vx *= 0.9;
      if (this.action === null && !this.crouching && !has(input.held, 'left') && !has(input.held, 'right')) {
        this.vx *= p.traction;
      }
      if (this.hitstun > 0) this.vx *= 0.9;
    } else {
      let grav = GRAVITY * p.gravity;
      if (this.floatTimer > 0) grav *= 0.38;
      if (this.fastfall) grav *= 1.25;
      if (this.action === 'attack') {
        if (dirX) {
          this.vx += dirX * 0.1;
          this.vx = Math.max(-p.airSpeed * 0.7, Math.min(p.airSpeed * 0.7, this.vx));
        }
      }
      if (this.action === 'shield') this.vx *= 0.96;
      this.vy += grav;
      const maxFall = this.fastfall ? MAX_FALL + 4 : MAX_FALL * p.gravity;
      if (this.vy > maxFall) this.vy = maxFall;

      if (this.action === null && !this.helpless && dirX) {
        this.facing = dirX;
      }
      // jump-cut on release
      if (this.vy < -4 && !has(input.held, 'jump') && !this.cutJump && this.action === null) {
        this.vy *= 0.58;
        this.cutJump = true;
      }
    }

    const prevY = this.y;
    this.x += this.vx;
    this.y += this.vy;

    this.collideStage(game, prevY);
    this.keepInBoundsSoftly(game);

    if (Math.abs(this.vx) > 8 || Math.abs(this.vy) > 10) {
      this.trail.push({ x: this.x, y: this.y, facing: this.facing, alpha: 0.42, color: this.char.palette.glow });
      if (this.trail.length > 7) this.trail.shift();
    }
    for (const t of this.trail) t.alpha *= 0.9;
    this.trail = this.trail.filter((t) => t.alpha > 0.04);
    if (this.action === 'dodge' && this.dodgeTimer <= this.dodgeIframes && this.dodgeTimer % 2 === 0) {
      this.trail.push({ x: this.x, y: this.y, facing: this.facing, alpha: 0.35, color: '#ffffff' });
    }
  }

  collideStage(game, prevY) {
    const platforms = [...game.stage.platforms].sort((a, b) => a.y - b.y);
    const halfPad = this.char.hurt.w * 0.32;
    let landed = false;

    if (this.vy >= 0) {
      for (const p of platforms) {
        const half = p.w / 2;
        if (this.x < p.x - half + halfPad * 0.3 || this.x > p.x + half - halfPad * 0.3) continue;
        if (prevY <= p.y + 3 && this.y >= p.y) {
          const impact = this.vy;
          this.y = p.y;
          this.vy = 0;
          this.grounded = true;
          landed = true;
          if (!this.wasGrounded) this.land(impact, game);
          break;
        }
      }
    }

    if (!landed) {
      let support = null;
      for (const p of platforms) {
        const half = p.w / 2;
        if (this.x >= p.x - half && this.x <= p.x + half && Math.abs(this.y - p.y) < 1.2) { support = p; break; }
      }
      if (support && this.vy >= 0) {
        this.y = support.y;
        this.vy = 0;
        if (!this.grounded && !this.wasGrounded) this.land(0, game);
        this.grounded = true;
      } else {
        if (this.grounded) {
          this.grounded = false;
          this.jumpsLeft = Math.min(this.jumpsLeft, 1);
        }
      }
    }
  }

  land(impact, game) {
    const hard = impact > 9;
    this.landSquash = hard ? 8 : 4;
    this.jumpsLeft = 2;
    this.airDodgeUsed = false;
    this.helpless = false;
    this.fastfall = false;
    this.cutJump = false;
    this.floatTimer = 0;
    this.airDodgeUsed = false;
    this.landSquash = hard ? 9 : 5;
    game.dust(this.x, this.y, 0, '#e9e4ff', hard ? 8 : 4);
    if (impact > 7) {
      if (this.hitstun > 0 && impact > 10) {
        this.vy = -impact * 0.42;
        this.y = this.y - 1.5;
        this.grounded = false;
        game.shake = Math.max(game.shake, 4);
        game.dust(this.x, this.y, 0, '#ffffff', 10);
        audio.land(1.4);
      } else {
        audio.land(Math.min(2, impact / 9));
      }
    }
  }

  keepInBoundsSoftly(game) {
    if (this.x < BLAST.left - 80) this.x = BLAST.left - 80;
    if (this.x > BLAST.right + 80) this.x = BLAST.right + 80;
  }

  postPhysics(game) {
    this.checkKO(game);
    this.checkHitsAfterPhysics?.();
  }

  checkKO(game) {
    if (!this.alive || this.koTimer > 0) return;
    const out = this.x < BLAST.left || this.x > BLAST.right || this.y > BLAST.bottom || this.y < BLAST.top;
    if (!out) return;
    this.stocks--;
    this.stats.falls++;
    if (this.stocks < 0) this.stocks = 0;
    this.koTimer = 78;
    this.action = 'ko';
    this.move = null;
    this.hitstun = 0;
    this.vx = 0;
    this.vy = 0;
    this.trail = [];
    const killer = this.lastHitBy !== null ? game.fighters[this.lastHitBy] : null;
    game.onKO(this, killer);
    if (this.stocks <= 0) this.eliminated = true;
  }

  respawn(game) {
    if (this.stocks <= 0) { this.eliminated = true; return; }
    this.x = Math.max(-520, Math.min(520, this.spawn.x));
    this.y = -260;
    this.vx = 0;
    this.vy = 0;
    this.damage = 0;
    this.action = null;
    this.move = null;
    this.attackFrame = 0;
    this.hitstun = 0;
    this.hitstop = 0;
    this.charging = false;
    this.helpless = false;
    this.grounded = false;
    this.jumpsLeft = 2;
    this.facing = this.x <= 0 ? 1 : -1;
    this.lastHitBy = null;
    this.invincible = 150;
    this.respawnGlow = 150;
    this.shieldHP = 100;
    this.airDodgeUsed = false;
    this.hitFlash = 0;
    this.koTimer = 0;
    game.respawnFx(this);
    audio.jump();
  }

  /** Called on match start/restart. */
  prepareMatch(stage, stocks) {
    this.reset(stage, stocks);
  }

  /** True if this fighter is hidden because they are exploding off-screen. */
  get invisible() {
    return this.koTimer > 0 || this.eliminated;
  }
}

export function circleRect(cx, cy, r, rect) {
  const nx = Math.max(rect.x, Math.min(cx, rect.x + rect.w));
  const ny = Math.max(rect.y, Math.min(cy, rect.y + rect.h));
  const dx = cx - nx;
  const dy = cy - ny;
  return dx * dx + dy * dy <= r * r;
}

export { ACTIONS };

// ---------------------------------------------------------------------------
// CPU brains — readable opponents that space, defend, and recover.
// ---------------------------------------------------------------------------
import { DIFFICULTIES } from './data.js';

const rnd = (a, b) => a + Math.random() * (b - a);
const chance = (p) => Math.random() < p;

export class AIBrain {
  constructor(fighter, difficulty = 2) {
    this.f = fighter;
    this.diff = DIFFICULTIES.find((d) => d.id === difficulty) || DIFFICULTIES[1];
    this.react = 0;
    this.attackCd = 0;
    this.specialCd = 30;
    this.jumpCd = 0;
    this.defendCd = 0;
    this.holdAttack = 0;
    this.holdShield = 0;
    this.strafe = 1;
    this.strafeTimer = 0;
    this.wander = 0;
    this.recoverJumped = false;
    this.recoverSpecial = false;
    this.targetSlot = null;
  }

  reset() {
    this.react = 0;
    this.attackCd = 0;
    this.specialCd = 20;
    this.jumpCd = 0;
    this.defendCd = 0;
    this.holdAttack = 0;
    this.holdShield = 0;
    this.recoverJumped = false;
    this.recoverSpecial = false;
    this.targetSlot = null;
  }

  nearestTarget(game) {
    let best = null;
    let bestD = Infinity;
    for (const other of game.fighters) {
      if (other === this.f || !other.alive || other.koTimer > 0) continue;
      const d = Math.hypot(other.x - this.f.x, other.y - this.f.y);
      if (d < bestD) { bestD = d; best = other; }
    }
    this.targetSlot = best ? best.slot : null;
    return best;
  }

  update(game) {
    const input = { held: new Set(), pressed: new Set() };
    const f = this.f;
    if (!f || f.eliminated || f.koTimer > 0) return input;
    if (game.phase !== 'fight' || game.freezeInput) return input;
    if (this.attackCd > 0) this.attackCd--;
    if (this.specialCd > 0) this.specialCd--;
    if (this.jumpCd > 0) this.jumpCd--;
    if (this.defendCd > 0) this.defendCd--;
    if (this.react > 0) this.react--;
    if (this.wander > 0) this.wander--;
    if (this.strafeTimer-- <= 0) {
      this.strafeTimer = Math.round(rnd(18, 55));
      this.strafe = chance(0.5) ? 1 : -1;
    }

    // Already committed to an action — do not stack inputs.
    if (f.action === 'attack' || f.action === 'dodge' || f.action === 'shieldbreak') {
      if (f.action === 'attack' && f.charging) {
        // let a charged smash rip once it is nasty enough
        if (f.charge > 18 + Math.round(Math.random() * 18)) return input;
        input.held.add('attack');
        return input;
      }
      return input;
    }
    if (f.action === 'shield') {
      if (this.holdShield > 0) {
        this.holdShield--;
        input.held.add('shield');
      }
      return input;
    }
    if (f.hitstun > 0) {
      return input;
    }

    if (this.holdAttack > 0) {
      this.holdAttack--;
      input.held.add('attack');
      if (this.attackDir) input.held.add(this.attackDir);
      return input;
    }

    const main = game.stage.platforms[0];
    const half = main.w / 2;
    const edgeMargin = 54;
    const offstage = f.x < main.x - half - 8 || f.x > main.x + half + 8 || f.y > 30;

    // ---- recovery ---------------------------------------------------------
    if (offstage && !f.grounded) {
      return this.recover(input, game, main, half);
    }
    this.recoverJumped = false;
    this.recoverSpecial = false;

    const target = this.nearestTarget(game);
    if (!target) return input;

    const dx = target.x - f.x;
    const dy = target.y - f.y;
    const dist = Math.hypot(dx, dy);
    const toward = dx >= 0 ? 'right' : 'left';
    const away = dx >= 0 ? 'left' : 'right';
    const outEdge = f.x < main.x - half + edgeMargin ? -1 : f.x > main.x + half - edgeMargin ? 1 : 0;
    const targetOffstage = target.x < main.x - half - 10 || target.x > main.x + half + 10 || target.y > 40;

    // ---- defense ----------------------------------------------------------
    if (this.defendCd <= 0 && dist < 165 && this.diff.defense > 0) {
      const targetThreat = (target.action === 'attack' || target.action === 'dodge') && target.facing === Math.sign(f.x - target.x);
      const projectileNear = game.projectiles.some((p) => p.owner !== f.slot
        && Math.hypot(p.x - f.x, p.y - (f.y - 40)) < 110
        && Math.sign(p.vx) === Math.sign(f.x - p.x));
      if ((targetThreat || projectileNear) && chance(this.diff.defense * 0.55)) {
        if (chance(0.55) && f.grounded && f.shieldHP > 35) {
          this.holdShield = Math.round(rnd(9, 19));
          this.defendCd = Math.round(rnd(38, 80));
          input.pressed.add('shield');
          input.held.add('shield');
          return input;
        }
        if (chance(0.6)) {
          this.defendCd = Math.round(rnd(50, 100));
          if (chance(0.6) && f.grounded) {
            input.pressed.add('dodge');
            input.held.add(away);
            return input;
          }
          if (!f.grounded && !f.airDodgeUsed) {
            input.pressed.add('dodge');
            input.held.add(away);
            return input;
          }
        }
      }
    }

    // ---- edgeguard --------------------------------------------------------
    if (targetOffstage && f.grounded) {
      const holdX = target.x > f.x ? 'right' : 'left';
      if (Math.abs(f.x - target.x) > 120 && outEdge === 0) input.held.add(holdX);
      if (!outEdge && this.specialCd <= 0 && Math.abs(target.x - f.x) < 460 && chance(0.5)) {
        this.specialCd = Math.round(rnd(55, 95));
        input.pressed.add('special');
        input.held.add(holdX);
        return input;
      }
      if (Math.abs(f.x - target.x) < 150 && chance(this.diff.aggression * 0.35)) {
        input.pressed.add('jump');
        this.jumpCd = 30;
        return input;
      }
      if (outEdge !== 0) input.held.add(outEdge > 0 ? 'left' : 'right');
      return input;
    }

    // ---- movement ---------------------------------------------------------
    let moveDir = 0;
    if (Math.abs(dx) > 66) moveDir = Math.sign(dx);
    else if (this.wander > 0) moveDir = this.strafe;
    else if (f.damage > 90 && chance(0.02)) this.wander = 22;

    // Don't sprint off the ledge unless chasing an offstage target.
    if (f.grounded && outEdge !== 0 && Math.sign(moveDir) === outEdge) moveDir = -outEdge;
    if (moveDir !== 0) input.held.add(moveDir > 0 ? 'right' : 'left');

    // Jump toward elevated targets / platforms.
    if (f.grounded && dy < -70 && this.jumpCd <= 0 && dist < 380 && chance(this.diff.aggression * 0.45)) {
      input.pressed.add('jump');
      this.jumpCd = Math.round(rnd(28, 55));
      this.recoverJumped = false;
      return input;
    }

    // ---- projectiles ------------------------------------------------------
    if (f.grounded && this.specialCd <= 0 && dist > 190 && Math.abs(dy) < 120
      && chance(this.diff.aggression * 0.55)) {
      this.specialCd = Math.round(rnd(70, 125));
      input.pressed.add('special');
      input.held.add(toward);
      return input;
    }

    // ---- attacks ----------------------------------------------------------
    if (this.react > 0) return input;

    const facing = Math.sign(dx) || 1;
    const canAttack = this.attackCd <= 0;
    if (!canAttack) return input;

    if (!f.grounded) {
      if (dist < 128) {
        this.attackCd = Math.round(rnd(14, 30));
        input.pressed.add('attack');
        if (target.y < f.y - 55) input.held.add('up');
        else if (target.y > f.y + 55) input.held.add('down');
        else input.held.add(toward);
        this.react = this.diff.reaction;
        return input;
      }
      return input;
    }

    // Grounded attack pick
    if (Math.abs(dy) > 90 && Math.abs(dx) < 110) {
      // target above/below on a platform
      this.attackCd = Math.round(rnd(16, 30));
      input.pressed.add('attack');
      input.held.add(dy < 0 ? 'up' : 'down');
      this.react = this.diff.reaction;
      return input;
    }

    if (dist < 168) {
      const wantCharge = f.damage < 80 && dist < 125 && chance(this.diff.aggression * 0.24);
      this.attackCd = Math.round(rnd(13, 26));
      this.react = this.diff.reaction;
      input.pressed.add('attack');
      if (dist > 74) {
        input.held.add(toward);
      } else if (chance(0.22)) {
        input.held.add('up');
      } else if (chance(0.12)) {
        input.held.add('down');
      }
      if (wantCharge && (input.held.has(toward) || input.held.has('up') || input.held.has('down'))) {
        this.holdAttack = Math.round(rnd(7, 20));
        this.attackDir = input.held.has(toward) ? toward : input.held.has('up') ? 'up' : 'down';
        input.held.add('attack');
      }
      return input;
    }

    // Close the gap with a dash attack sometimes.
    if (dist < 260 && chance(this.diff.aggression * 0.25)) {
      this.attackCd = Math.round(rnd(20, 38));
      this.react = this.diff.reaction;
      input.pressed.add('attack');
      input.held.add(toward);
      return input;
    }

    if (facing !== 0 && outEdge === Math.sign(dx) && f.grounded) {
      input.held.add(toward);
    }
    return input;
  }

  recover(input, game, main, half) {
    const f = this.f;
    const cx = main.x;
    const towardC = cx >= f.x ? 'right' : 'left';
    const far = Math.abs(f.x - cx) > half - 30;
    const skill = this.diff.recovery;

    if (far || f.x < cx - half || f.x > cx + half) input.held.add(towardC);
    else if (f.x < cx - half + 40) input.held.add('right');
    else if (f.x > cx + half - 40) input.held.add('left');

    // Jump back toward the stage.
    if (!this.recoverJumped && f.jumpsLeft > 0 && f.vy > -2 && f.y > -120 && chance(skill)) {
      this.recoverJumped = true;
      input.pressed.add('jump');
      return input;
    }

    // Up-special when below the stage lip.
    const deep = f.y > 35 || far;
    if (!this.recoverSpecial && !f.helpless && deep
      && (f.jumpsLeft <= 1 || f.y > 40) && chance(skill)) {
      this.recoverSpecial = true;
      input.pressed.add('special');
      input.held.add('up');
      return input;
    }

    // Fall back on side special if the up special is spent.
    if (this.recoverSpecial && !this.recoverJumped && f.helpless && chance(0.1)) {
      input.held.add(towardC);
    }
    return input;
  }
}

// ---------------------------------------------------------------------------
// Game — match lifecycle, projectiles, effects, camera and scoring.
// ---------------------------------------------------------------------------
import { Fighter } from './fighter.js';
import { AIBrain } from './ai.js';
import { STAGE_MAP, BLAST, SLOT_COLORS, SLOT_NAMES } from './data.js';
import { audio } from './audio.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const EMPTY_INPUT = { held: new Set(), pressed: new Set() };

export class Game {
  constructor() {
    this.phase = 'idle';
    this.fighters = [];
    this.projectiles = [];
    this.particles = [];
    this.popups = [];
    this.announcement = null;
    this.stage = STAGE_MAP.sky;
    this.config = null;
    this.time = 0;
    this.clock = 0;
    this.hitstop = 0;
    this.shake = 0;
    this.screenFlash = 0;
    this.flashColor = '#ffffff';
    this.camera = { x: 0, y: -80, zoom: 1, punch: 0 };
    this.view = { w: 1280, h: 720 };
    this.countdown = 0;
    this.overTimer = 0;
    this.ending = false;
    this.results = null;
    this.elimOrder = [];
    this.onEnd = null;
    this.ais = [];
    this.initialized = false;
    this.slowmo = 0;
    this.matchSeed = Math.random() * 1000;
  }

  start(config, onEnd) {
    this.config = {
      ...config,
      slots: config.slots.map((s) => ({ ...s })),
    };
    this.stage = STAGE_MAP[config.stage] || STAGE_MAP.sky;
    this.fighters = [];
    this.projectiles = [];
    this.particles = [];
    this.popups = [];
    this.announcement = null;
    this.ais = [];
    this.elimOrder = [];
    this.results = null;
    this.onEnd = onEnd || null;
    this.time = 0;
    this.clock = 0;
    this.hitstop = 0;
    this.shake = 0;
    this.screenFlash = 0;
    this.ending = false;
    this.overTimer = 0;
    this.phase = 'countdown';
    this.countdown = 0;
    this.camera = { x: 0, y: -90, zoom: 1, punch: 0 };
    this.initialized = true;

    config.slots.forEach((slot, index) => {
      if (slot.type === 'off') return;
      const f = new Fighter(index, slot.char, slot.type, config.difficulty, this.stage);
      f.prepareMatch(this.stage, config.stocks);
      f.invincible = 70;
      this.fighters.push(f);
      if (slot.type === 'cpu') this.ais.push(new AIBrain(f, config.difficulty));
    });

    for (const f of this.fighters) {
      this.ring(f.x, f.y - 30, f.color, 40);
      this.burst(f.x, f.y - 40, f.color, 8, 3);
    }
    this.updateCamera(true);
    this.announce('3', this.stage.name, '#ffffff', 22);
    this.countdownStep = 0;
    audio.beep(false);
  }

  restart() {
    if (!this.config) return;
    const cb = this.onEnd;
    this.start(this.config, cb);
  }

  announce(text, sub = '', color = '#ffffff', life = 62) {
    this.announcement = {
      text, sub, color, life, maxLife: life, id: Math.random(),
    };
  }

  // -------------------------------------------------------------------------
  update(humanInputs = []) {
    if (!this.initialized) return;
    this.time++;
    this.updateParticles();
    this.updatePopups();

    if (this.announcement) {
      this.announcement.life--;
      if (this.announcement.life <= 0) this.announcement = null;
    }
    this.shake *= 0.88;
    if (this.shake < 0.15) this.shake = 0;
    this.screenFlash = Math.max(0, this.screenFlash - 0.035);
    this.camera.punch *= 0.9;

    if (this.phase === 'countdown') {
      this.countdown++;
      this.updateFightersCountdown();
      this.updateCamera();
      this.tickCountdown();
      return;
    }

    if (this.phase === 'over') {
      this.overTimer--;
      this.updateFightersIdle(humanInputs);
      this.updateProjectiles();
      this.updateCamera();
      if (this.overTimer <= 0) this.finish();
      return;
    }

    if (this.phase === 'ended') {
      this.updateCamera();
      return;
    }

    this.clock++;

    if (this.hitstop > 0) {
      this.hitstop--;
      this.updateCamera();
      return;
    }

    for (const f of this.fighters) {
      let input = EMPTY_INPUT;
      if (!f.eliminated && f.koTimer <= 0) {
        if (f.kind === 'cpu') {
          const brain = this.ais.find((a) => a.f === f);
          input = brain ? brain.update(this) : EMPTY_INPUT;
        } else {
          input = humanInputs[f.slot] || EMPTY_INPUT;
        }
      }
      f.update(input, this);
    }
    this.updateProjectiles();
    this.checkEnd();
    this.updateCamera();
  }

  updateFightersCountdown() {
    for (const f of this.fighters) {
      if (f.eliminated) continue;
      f.update(EMPTY_INPUT, this);
    }
  }

  updateFightersIdle(inputs) {
    for (const f of this.fighters) {
      f.update(EMPTY_INPUT, this);
    }
  }

  tickCountdown() {
    const marks = [0, 26, 52, 78];
    const labels = ['3', '2', '1'];
    if (this.countdown === marks[1] - 0) {
      this.announce('2', this.stage.name, '#ffffff', 22);
      audio.beep(false);
    } else if (this.countdown === marks[2]) {
      this.announce('1', this.stage.name, '#ffe08a', 22);
      audio.beep(false);
    } else if (this.countdown === marks[3]) {
      this.phase = 'fight';
      this.announce('GO!', '', '#b6ff5c', 34);
      audio.beep(true);
      audio.announce();
    }
  }

  checkEnd() {
    if (this.ending) return;
    const alive = this.fighters.filter((f) => f.stocks > 0 && !f.eliminated);
    if (alive.length <= 1 && this.fighters.length >= 2) {
      this.ending = true;
      this.phase = 'over';
      this.overTimer = 112;
      const winner = alive[0];
      if (winner) {
        this.announce('GAME!', `${winner.tag} WINS`, winner.color, 110);
      } else {
        this.announce('GAME!', 'DOUBLE KO', '#ffd75e', 110);
      }
      this.screenFlash = 0.4;
      this.flashColor = '#ffffff';
      for (let i = 0; i < 30; i++) {
        this.addParticle({
          type: 'confetti', x: (Math.random() - 0.5) * 900, y: -420 - Math.random() * 300,
          vx: (Math.random() - 0.5) * 3, vy: 1 + Math.random() * 3, size: 4 + Math.random() * 5,
          color: ['#ffd75e', '#ff7a3d', '#ff3d8b', '#45e3ff', '#b6ff5c'][i % 5],
          life: 180 + Math.random() * 80, maxLife: 240, rot: Math.random() * 6, vr: (Math.random() - 0.5) * 0.2,
        });
      }
      audio.win();
    }
  }

  finish() {
    if (this.phase === 'ended') return;
    this.phase = 'ended';
    this.results = this.buildResults();
    if (this.onEnd) this.onEnd(this.results);
  }

  buildResults() {
    const survivors = this.fighters
      .filter((f) => f.stocks > 0 && !f.eliminated)
      .sort((a, b) => b.stocks - a.stocks || a.damage - b.damage);
    const eliminated = this.elimOrder
      .slice()
      .reverse()
      .map((slot) => this.fighters.find((f) => f.slot === slot))
      .filter(Boolean);
    const ordered = [...survivors, ...eliminated];
    const rows = ordered.map((f, i) => ({
      slot: f.slot,
      tag: f.tag,
      charId: f.charId,
      charName: f.char.name,
      kind: f.kind,
      color: f.color,
      placement: i + 1,
      stocks: f.stocks,
      damage: Math.round(f.damage),
      kos: f.stats.kos,
      falls: f.stats.falls,
      dealt: Math.round(f.stats.dealt),
    }));
    return {
      rows,
      winner: survivors[0] || null,
      winnerSlot: survivors[0] ? survivors[0].slot : null,
      duration: this.clock,
      stage: this.stage,
    };
  }

  // -------------------------------------------------------------------------
  respawnFx(f) {
    this.ring(f.x, f.y - 40, f.color, 90);
    this.ring(f.x, f.y - 40, '#ffffff', 50);
    this.burst(f.x, f.y - 40, f.color, 14, 5);
  }

  onHit(attacker, victim, dmg) {
    const color = attacker ? attacker.char.palette.glow : '#ffffff';
    const heavy = dmg > 13;
    this.burst(victim.x, victim.y - 44, '#fff3d0', heavy ? 14 : 8, heavy ? 7 : 4.5);
    this.burst(victim.x, victim.y - 44, color, heavy ? 8 : 4, 5);
    this.sparkArc(victim.x, victim.y - 46, Math.atan2(victim.vy, victim.vx), color, heavy);
    this.popup(victim.x, victim.y - 78, `${Math.ceil(dmg)}`, dmg >= 18 ? '#ff5470' : dmg >= 11 ? '#ffb347' : '#fff3d0', heavy ? 1.25 : 1);
    if (attacker) {
      const card = document.querySelector(`.hud-card[data-slot="${victim.slot}"]`);
      if (card) {
        card.classList.remove('shake');
        void card.offsetWidth;
        card.classList.add('shake');
      }
    }
  }

  onShieldHit(attacker, victim) {
    this.burst(victim.x, victim.y - 48, '#8fe9ff', 8, 4);
    this.ring(victim.x, victim.y - 46, '#8fe9ff', 30);
    this.popup(victim.x, victim.y - 82, 'BLOCK', '#8fe9ff', 0.8);
    this.shake = Math.max(this.shake, 3);
  }

  onCounter(defender, attacker) {
    this.ring(defender.x, defender.y - 45, '#ffffff', 56);
    this.burst(defender.x, defender.y - 45, defender.char.palette.glow, 18, 6);
    this.popup(defender.x, defender.y - 95, 'COUNTER!', defender.char.palette.glow, 1.1);
    this.screenFlash = Math.max(this.screenFlash, 0.3);
    this.flashColor = '#ffffff';
    this.shake = Math.max(this.shake, 8);
  }

  onKO(fighter, killer) {
    const x = clamp(fighter.x, BLAST.left + 40, BLAST.right - 40);
    const y = clamp(fighter.y, BLAST.top + 60, BLAST.bottom - 40);
    for (let i = 0; i < 26; i++) {
      this.addParticle({
        type: 'spark', x, y,
        vx: (Math.random() - 0.5) * 24, vy: (Math.random() - 0.5) * 24,
        life: 28 + Math.random() * 28, maxLife: 56, size: 2 + Math.random() * 5,
        color: ['#ffffff', '#ffd75e', '#ff7a3d', fighter.color][i % 4], grav: 0.25,
      });
    }
    for (let i = 0; i < 8; i++) {
      this.addParticle({
        type: 'ring', x, y, vx: 0, vy: 0, life: 26 + i * 4, maxLife: 56,
        size: 20 + i * 14, color: i % 2 ? fighter.color : '#ffffff', grav: 0,
      });
    }
    this.addParticle({
      type: 'beam', x, y, vx: 0, vy: 0, life: 38, maxLife: 38, size: 220,
      color: fighter.color, grav: 0, rot: Math.atan2(y, x) + Math.PI / 2,
    });
    this.popup(x, y - 30, 'KO!', '#fff', 1.6);
    this.shake = 18;
    this.screenFlash = 0.72;
    this.flashColor = '#fff6e6';
    this.hitstop = Math.max(this.hitstop, 14);
    this.camera.punch = 0.1;
    audio.ko();
    if (killer && killer !== fighter) killer.stats.kos++;
    if (fighter.stocks <= 0) {
      this.elimOrder.push(fighter.slot);
      this.announce('ELIMINATED', `${fighter.tag} · ${fighter.char.name}`, fighter.color, 60);
    } else {
      this.announce('KO!', `${fighter.tag} LOSES A STOCK`, fighter.color, 46);
    }
  }

  // -------------------------------------------------------------------------
  updateProjectiles() {
    const keep = [];
    for (const p of this.projectiles) {
      p.life--;
      if (p.life <= 0) continue;
      p.vy += p.gravity;
      const prevY = p.y;
      p.x += p.vx;
      p.y += p.vy;
      p.rot = (p.rot || 0) + (p.kind === 'seed' ? 0.18 : 0.35);
      if (Math.random() < 0.55) {
        this.addParticle({
          type: 'trail', x: p.x, y: p.y, vx: -p.vx * 0.08, vy: -p.vy * 0.08,
          life: 12, maxLife: 12, size: p.r * 0.7, color: p.color, grav: 0,
        });
      }
      // bounce seed or projectile off the main stage surface
      let bounced = false;
      for (const plat of this.stage.platforms) {
        const half = plat.w / 2;
        if (p.x < plat.x - half || p.x > plat.x + half) continue;
        if (prevY <= plat.y && p.y >= plat.y && p.vy > 0) {
          if (p.bounce > 0) {
            p.y = plat.y - 1;
            p.vy = -Math.abs(p.vy) * 0.62;
            p.vx *= 0.86;
            p.bounce--;
            bounced = true;
            this.dust(p.x, plat.y, 0, p.color, 3);
            break;
          }
          if (p.kind === 'seed') {
            this.burst(p.x, plat.y - 8, p.color, 8, 3);
            p.life = 0;
            break;
          }
        }
      }
      if (bounced) { keep.push(p); continue; }
      if (p.life <= 0) continue;

      // bounds
      if (p.x < BLAST.left || p.x > BLAST.right || p.y < BLAST.top || p.y > BLAST.bottom) continue;

      // projectile vs projectile
      let clashed = false;
      for (const q of keep) {
        if (q.owner === p.owner) continue;
        if (Math.hypot(q.x - p.x, q.y - p.y) < q.r + p.r) {
          this.burst((p.x + q.x) / 2, (p.y + q.y) / 2, '#ffffff', 10, 4);
          this.ring((p.x + q.x) / 2, (p.y + q.y) / 2, '#8fe9ff', 24);
          q.life = 0;
          clashed = true;
          break;
        }
      }
      if (clashed) { p.life = 0; continue; }

      // projectile vs fighters
      for (const f of this.fighters) {
        if (f.eliminated || f.koTimer > 0 || f.slot === p.owner) continue;
        const box = f.hurtbox();
        if (circleRect(p.x, p.y, p.r, box)) {
          if (f.isCountering()) {
            p.owner = f.slot;
            p.vx *= -1.4;
            p.vy = -Math.abs(p.vy) * 0.7 - 1;
            p.damage *= 1.35;
            p.speed = Math.abs(p.vx);
            p.life = Math.max(40, p.life);
            p.color = f.char.palette.glow;
            this.burst(p.x, p.y, '#ffffff', 12, 6);
            this.onCounter(f, this.fighters[p.owner]);
            audio.counter();
            p.x += p.vx * 2;
            break;
          }
          const move = {
            damage: p.damage, baseKB: p.baseKB, growth: p.growth, angle: p.angle,
          };
          const owner = this.fighters.find((x) => x.slot === p.owner);
          const dir = Math.sign(p.vx) || 1;
          const res = f.takeHit(move, owner, 1, this, { dir });
          if (res === 'hit') {
            if (owner) owner.stats.dealt += p.damage;
            this.hitstop = Math.max(this.hitstop, 3);
            this.onHit(owner, f, p.damage);
          } else if (res === 'shield') {
            this.onShieldHit(owner, f);
            this.hitstop = Math.max(this.hitstop, 2);
          } else if (res === 'countered') {
            this.hitstop = Math.max(this.hitstop, 5);
          }
          p.life = 0;
          break;
        }
      }
      if (p.life > 0) keep.push(p);
    }
    this.projectiles = keep;
  }

  // -------------------------------------------------------------------------
  updateCamera(instant = false) {
    const live = this.fighters.filter((f) => f.alive && f.koTimer <= 0);
    const vw = this.view.w || 1280;
    const vh = this.view.h || 720;
    const base = vh / 720;
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;
    if (live.length) {
      for (const f of live) {
        minX = Math.min(minX, f.x);
        maxX = Math.max(maxX, f.x);
        minY = Math.min(minY, f.y - 100);
        maxY = Math.max(maxY, f.y);
      }
    } else {
      minX = -300; maxX = 300; minY = -260; maxY = 0;
    }
    const spreadX = Math.max(520, maxX - minX + 480);
    const spreadY = Math.max(420, maxY - minY + 380);
    let zoomX = (vw * 0.92) / (spreadX * base);
    let zoomY = (vh * 0.82) / (spreadY * base);
    let zoom = Math.min(zoomX, zoomY, 1.16);
    zoom = clamp(zoom, 0.42, 1.16);
    if (live.length === 1) zoom = Math.min(zoom, 0.95);

    const tx = (minX + maxX) / 2;
    const ty = (minY + maxY) / 2 - 24;
    const ease = instant ? 1 : 0.09;
    this.camera.x += (tx - this.camera.x) * ease;
    this.camera.y += (ty - this.camera.y) * ease;
    this.camera.zoom += (zoom - this.camera.zoom) * (instant ? 1 : 0.06);
  }

