// Shared canvas drawing helpers.
export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;

export function hexA(hex, a) {
  if (!hex) return `rgba(255,255,255,${a})`;
  if (hex.startsWith('rgba') || hex.startsWith('rgb')) return hex;
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const n = parseInt(h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}

export function mix(hex1, hex2, t) {
  if (!hex1 || !hex2) return hex1 || hex2 || '#fff';
  let a = hex1.replace('#', '');
  let b = hex2.replace('#', '');
  if (a.length === 3) a = a.split('').map((c) => c + c).join('');
  if (b.length === 3) b = b.split('').map((c) => c + c).join('');
  const na = parseInt(a, 16);
  const nb = parseInt(b, 16);
  const r = Math.round(lerp((na >> 16) & 255, (nb >> 16) & 255, t));
  const g = Math.round(lerp((na >> 8) & 255, (nb >> 8) & 255, t));
  const bl = Math.round(lerp(na & 255, nb & 255, t));
  return `rgb(${r},${g},${bl})`;
}

export function shade(hex, amount) {
  return mix(hex, amount < 0 ? '#000000' : '#ffffff', Math.abs(amount));
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.max(0, Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2));
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function poly(ctx, pts) {
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.closePath();
}

export function starPath(ctx, r1, r2, points, rot = 0) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 ? r2 : r1;
    const a = rot + (i / (points * 2)) * TAU - Math.PI / 2;
    const x = Math.cos(a) * r;
    const y = Math.sin(a) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

export function capsule(ctx, ax, ay, bx, by, bend, width, color, outline = null) {
  const mx = (ax + bx) / 2;
  const my = (ay + by) / 2;
  const dx = bx - ax;
  const dy = by - ay;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;
  const cx = mx + nx * bend;
  const cy = my + ny * bend;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  if (outline) {
    ctx.strokeStyle = outline;
    ctx.lineWidth = width + 3;
    ctx.beginPath();
    ctx.moveTo(ax, ay);
    ctx.quadraticCurveTo(cx, cy, bx, by);
    ctx.stroke();
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(ax, ay);
  ctx.quadraticCurveTo(cx, cy, bx, by);
  ctx.stroke();
}

export function limb2(ctx, ax, ay, bx, by, bend1, bend2, width, color, outline) {
  const mx = (ax + bx) / 2;
  const my = (ay + by) / 2;
  const dx = bx - ax;
  const dy = by - ay;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;
  const jx = mx + nx * bend1 + dx * bend2;
  const jy = my + ny * bend1 + dy * bend2;
  capsule(ctx, ax, ay, jx, jy, bend1 * 0.15, width, color, outline);
  capsule(ctx, jx, jy, bx, by, bend1 * 0.1 + bend2 * 20, width * 0.86, color, outline);
}

export function glowCircle(ctx, x, y, r, color, alpha = 0.6) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, hexA(color, alpha));
  g.addColorStop(0.5, hexA(color, alpha * 0.4));
  g.addColorStop(1, hexA(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
}

export function withOutline(ctx, fill, outline, draw) {
  draw();
  ctx.fillStyle = fill;
  ctx.fill();
  if (outline) {
    ctx.strokeStyle = outline;
    ctx.lineWidth = 2;
    ctx.stroke();
  }
}

// ---------------------------------------------------------------------------
// Figure — procedural fighter art, poses, faces and accessories.
// ---------------------------------------------------------------------------
import { CHAR_MAP } from './data.js';
import {
  TAU, clamp, hexA, mix, shade, capsule, limb2, poly, glowCircle,
  roundRect, starPath,
} from './draw-utils.js';

const OUTLINE = '#1a1122';

export function buildPose(f, time) {
  const t = (f.animTime ?? time) + (f.slot || 0) * 13;
  const grounded = f.grounded !== false;
  const speed = Math.abs(f.vx || 0);
  const bob = grounded ? Math.sin(t * 0.06) * 1.5 : 0;

  const p = {
    bob, lean: 0, spin: 0, headTilt: 0,
    hipY: -40 + bob, shoulderY: -70 + bob, headY: -88 + bob, headX: 1,
    headR: 15,
    frontHand: { x: 20, y: -49 + bob }, backHand: { x: -17, y: -50 + bob },
    frontFoot: { x: 13, y: 0 }, backFoot: { x: -14, y: 0 },
    armBendF: 4, armBendB: -4, legBendF: 2, legBendB: -2,
    glow: 0, shield: false, scarf: 0,
  };

  // --- locomotion ----------------------------------------------------------
  if (grounded && !f.action && speed > 1.4) {
    const ph = f.runPhase || t * 0.15;
    const swing = Math.sin(ph);
    p.frontFoot = { x: 10 + swing * 18, y: -Math.max(0, swing) * 9 };
    p.backFoot = { x: 10 - swing * 18, y: -Math.max(0, -swing) * 9 };
    p.frontHand = { x: 18 - swing * 11, y: -52 };
    p.backHand = { x: -16 + swing * 11, y: -52 };
    p.lean = 0.055 + Math.min(0.06, speed * 0.008);
    p.hipY = -41 + Math.abs(swing) * 2;
    p.shoulderY = -70 + Math.abs(swing) * 2;
    p.headY = -88 + Math.abs(swing) * 2;
  } else if (grounded && !f.action && !f.crouching) {
    p.frontHand.x += Math.sin(t * 0.06) * 1.4;
    p.backHand.x -= Math.sin(t * 0.06) * 1.4;
  }

  if (f.crouching && grounded) {
    p.hipY += 12;
    p.shoulderY += 11;
    p.headY += 10;
    p.frontFoot = { x: 17, y: 0 };
    p.backFoot = { x: -17, y: 0 };
    p.frontHand = { x: 16, y: -40 };
    p.backHand = { x: -13, y: -42 };
  }

  if (!grounded) {
    const rising = (f.vy || 0) < -2;
    p.legBendF = rising ? 12 : 4;
    p.legBendB = rising ? -10 : -4;
    p.frontFoot = { x: rising ? 15 : 9, y: rising ? -12 : 2 };
    p.backFoot = { x: rising ? -7 : -12, y: rising ? -4 : 0 };
    p.frontHand = { x: rising ? 25 : 30, y: rising ? -78 : -62 };
    p.backHand = { x: rising ? -24 : -30, y: rising ? -70 : -58 };
    p.lean = rising ? 0.04 : -0.03;
    if (f.fastfall) {
      p.frontHand = { x: 12, y: -98 };
      p.backHand = { x: -12, y: -98 };
      p.frontFoot = { x: 8, y: 4 };
      p.backFoot = { x: -8, y: 2 };
    }
  }

  // --- shield / break ------------------------------------------------------
  if (f.action === 'shield') {
    p.hipY += 9; p.shoulderY += 8; p.headY += 7;
    p.frontHand = { x: 11, y: -58 };
    p.backHand = { x: 6, y: -62 };
    p.frontFoot = { x: 16, y: 0 };
    p.backFoot = { x: -16, y: 0 };
    p.shield = true;
    p.lean = -0.05;
  }
  if (f.action === 'shieldbreak') {
    p.lean = Math.sin(t * 0.28) * 0.16;
    p.headTilt = Math.sin(t * 0.22) * 0.24;
    p.frontHand = { x: 20, y: -36 };
    p.backHand = { x: -20, y: -38 };
    p.frontFoot = { x: 18, y: 0 };
    p.backFoot = { x: -18, y: 0 };
  }

  // --- hitstun -------------------------------------------------------------
  if (f.hitstun > 0) {
    p.lean = -0.32 - Math.min(0.2, (f.hitstun || 0) / 120);
    p.headTilt = -0.2;
    p.frontHand = { x: 14, y: -88 };
    p.backHand = { x: -26, y: -76 };
    p.frontFoot = { x: 24, y: -10 };
    p.backFoot = { x: -8, y: -2 };
    p.legBendF = 10;
    p.legBendB = -6;
    if (f.tumble) p.spin = Math.sin(t * 0.26) * 0.34;
  }

  // --- dodge ---------------------------------------------------------------
  if (f.action === 'dodge') {
    const prog = (f.dodgeTimer || 0) / Math.max(1, f.dodgeDuration || 18);
    if (grounded) {
      p.spin = prog * TAU;
      p.hipY += 10; p.shoulderY += 10; p.headY += 9;
      p.frontHand = { x: 13, y: -46 };
      p.backHand = { x: -10, y: -46 };
      p.frontFoot = { x: 10, y: -7 };
      p.backFoot = { x: -9, y: -7 };
    } else {
      p.lean = 0.12;
      p.frontHand = { x: 24, y: -88 };
      p.backHand = { x: -24, y: -86 };
      p.frontFoot = { x: 14, y: -6 };
      p.backFoot = { x: -13, y: -3 };
    }
  }

  // --- respawn -------------------------------------------------------------
  if (f.respawnGlow > 0 && f.action !== 'shield') {
    p.frontHand = { x: 26, y: -72 };
    p.backHand = { x: -24, y: -70 };
    p.frontFoot = { x: 9, y: -4 };
    p.backFoot = { x: -8, y: -2 };
    p.glow = 1;
  }

  // --- attacks -------------------------------------------------------------
  if (f.action === 'attack' && f.move) {
    const m = f.move;
    const d = f.attackFrame || 0;
    const start = m.startup || 4;
    const end = start + (m.active || 3);
    const total = end + (m.recovery || 10);
    const wind = clamp(d / start, 0, 1);
    const active = d >= start && d < end;
    const rec = d >= end ? clamp((d - end) / Math.max(1, m.recovery), 0, 1) : 0;
    const ext = active ? 1 : d < start ? Math.sin(wind * Math.PI * 0.5) * 0.28 : 1 - rec;
    const anim = m.anim || 'jab';

    if (anim === 'jab') {
      p.frontHand = { x: 12 + ext * 37, y: -64 - ext * 2 };
      p.backHand = { x: -14, y: -60 };
      p.lean = 0.05 + ext * 0.1;
      p.frontFoot = { x: 20, y: 0 };
    } else if (anim === 'side') {
      p.lean = -0.06 + ext * 0.26;
      p.frontHand = { x: 6 + ext * 50, y: -70 + ext * 8 };
      p.backHand = { x: -20 - ext * 8, y: -56 };
      p.frontFoot = { x: 22 + ext * 12, y: 0 };
      p.backFoot = { x: -18, y: 0 };
    } else if (anim === 'up') {
      p.hipY += 8; p.shoulderY += 6; p.headY += 5;
      p.frontHand = { x: 12, y: -80 - ext * 46 };
      p.backHand = { x: -18, y: -62 };
      p.headTilt = -0.18;
      p.frontFoot = { x: 17, y: 0 };
      p.backFoot = { x: -17, y: 0 };
    } else if (anim === 'down') {
      p.hipY += 13; p.shoulderY += 11; p.headY += 10;
      p.lean = 0.12;
      p.frontFoot = { x: 18 + ext * 30, y: -3 };
      p.backFoot = { x: -19, y: 0 };
      p.frontHand = { x: -12, y: -32 };
      p.backHand = { x: -24, y: -42 };
    } else if (anim === 'dash') {
      p.lean = 0.3 + ext * 0.12;
      p.frontHand = { x: 34 + ext * 12, y: -58 };
      p.backHand = { x: -26, y: -68 };
      p.frontFoot = { x: 20, y: -6 };
      p.backFoot = { x: -20, y: -8 };
    } else if (anim === 'nair') {
      p.spin = d * 0.3;
      p.frontHand = { x: 34, y: -62 };
      p.backHand = { x: -34, y: -62 };
      p.frontFoot = { x: 15, y: -12 };
      p.backFoot = { x: -14, y: -10 };
      p.legBendF = 10; p.legBendB = -10;
    } else if (anim === 'fair') {
      p.lean = 0.15;
      p.frontHand = { x: 20 + ext * 34, y: -78 };
      p.backHand = { x: -8 + ext * 20, y: -66 };
      p.frontFoot = { x: -6, y: -8 };
      p.backFoot = { x: -20, y: -4 };
    } else if (anim === 'uair') {
      p.spin = d * 0.18;
      p.frontHand = { x: 13, y: -118 };
      p.backHand = { x: -13, y: -110 };
      p.frontFoot = { x: 8, y: -10 };
      p.backFoot = { x: -8, y: -8 };
      p.headTilt = -0.2;
    } else if (anim === 'dair') {
      p.frontHand = { x: 16, y: -104 };
      p.backHand = { x: -16, y: -104 };
      p.frontFoot = { x: 8, y: 2 };
      p.backFoot = { x: -7, y: 1 };
      p.lean = 0.04;
    } else if (anim === 'cast') {
      p.frontHand = { x: 16 + ext * 32, y: -62 };
      p.backHand = { x: 6 + ext * 30, y: -58 };
      p.lean = -0.04 + ext * 0.06;
      p.frontFoot = { x: 20, y: 0 };
      p.backFoot = { x: -18, y: 0 };
      p.glow = 0.7 + ext * 0.3;
    } else if (anim === 'lunge') {
      p.lean = 0.32 + ext * 0.14;
      p.frontHand = { x: 24 + ext * 26, y: -56 };
      p.backHand = { x: -28, y: -70 };
      p.frontFoot = { x: 15, y: -8 };
      p.backFoot = { x: -24, y: -10 };
      p.glow = 0.5 + ext * 0.5;
    } else if (anim === 'rise') {
      p.hipY -= 4; p.shoulderY -= 5; p.headY -= 5;
      p.frontHand = { x: 9, y: -86 - ext * 46 };
      p.backHand = { x: -12, y: -64 };
      p.frontFoot = { x: 7, y: -8 };
      p.backFoot = { x: -5, y: -3 };
      p.headTilt = -0.18;
      p.glow = 1;
    } else if (anim === 'counter') {
      p.hipY += 8; p.shoulderY += 7; p.headY += 6;
      p.frontHand = { x: 14, y: -60 };
      p.backHand = { x: 2, y: -64 };
      p.frontFoot = { x: 19, y: 0 };
      p.backFoot = { x: -19, y: 0 };
      p.lean = -0.08;
      p.glow = 0.45 + (f.counterFlash ? 1 : 0);
    } else if (anim === 'lash') {
      p.lean = -0.04 + ext * 0.16;
      p.frontHand = { x: 16 + ext * 56, y: -60 };
      p.backHand = { x: -24, y: -58 };
      p.frontFoot = { x: 22, y: 0 };
      p.backFoot = { x: -20, y: 0 };
      p.glow = 0.6;
    } else {
      p.frontHand = { x: 14 + ext * 32, y: -64 };
      p.lean = ext * 0.12;
    }

    if (f.charging) {
      p.lean -= 0.12;
      p.frontHand = { x: 0, y: -50 };
      p.backHand = { x: -18, y: -48 };
      p.hipY += 5; p.shoulderY += 4; p.headY += 3;
      p.bob += Math.sin(t * 0.9) * 1.2;
      p.glow = 1;
    }
    if (f.armor) p.glow = Math.max(p.glow, 0.4);
  }

  if (f.landSquash > 0) {
    const s = f.landSquash / 9;
    p.hipY += 4 * s;
    p.shoulderY += 4 * s;
    p.headY += 3 * s;
    p.frontFoot.x += 6 * s;
    p.backFoot.x -= 6 * s;
  }
  return p;
}

// ---------------------------------------------------------------------------
// Main fighter draw
// ---------------------------------------------------------------------------
export function drawFighter(ctx, f, time, opts = {}) {
  if (!f || f.invisible) return;
  const char = f.char || CHAR_MAP[f.charId];
  if (!char) return;
  const size = char.physics.size || 1;
  const facing = f.facing || 1;
  const p = buildPose(f, time);
  const P = char.palette;
  const flicker = f.invincible > 0 && Math.floor((f.animTime || time) / 3) % 2 === 0 && f.hitstun <= 0;

  ctx.save();
  ctx.translate(f.x, f.y);

  if (f.respawnGlow > 0) {
    const a = Math.min(0.5, f.respawnGlow / 120);
    glowCircle(ctx, 0, -52, 70, P.glow, a);
  }
  if (f.damage >= 100 && f.alive !== false) {
    glowCircle(ctx, 0, -50, 64, '#ff2f4f', Math.min(0.3, (f.damage - 80) / 400));
  }

  ctx.scale(size * facing, size);
  if (typeof opts.fade === 'number') ctx.globalAlpha = opts.fade;

  // rotate around the torso for spins and leans
  if (p.spin) {
    ctx.translate(0, -40);
    ctx.rotate(p.spin);
    ctx.translate(0, 40);
  }
  if (p.lean) {
    ctx.translate(0, -38);
    ctx.rotate(p.lean);
    ctx.translate(0, 38);
  }

  drawFigure(ctx, f, char, p, P, opts);

  if (f.hitFlash > 4) {
    ctx.globalAlpha = Math.min(0.75, f.hitFlash / 12);
    const white = { skin: '#fff', primary: '#fff', secondary: '#fff', trim: '#fff', hair: '#fff', glow: '#fff', accent: '#fff' };
    drawFigure(ctx, f, char, p, white, { ...opts, flat: true });
    ctx.globalAlpha = 1;
  }
  if (flicker) ctx.globalAlpha = 1;
  ctx.restore();
}

function drawFigure(ctx, f, char, p, P, opts) {
  const id = char.id;
  const bulk = id === 'glacier' ? 1.28 : id === 'volt' ? 0.9 : id === 'sprout' ? 0.94 : 1;
  const hipW = 20 * bulk;
  const shoulderW = 25 * bulk;
  const armW = 8 * bulk;
  const legW = 9.5 * bulk;
  const outline = opts.flat ? null : OUTLINE;
  const darkP = opts.flat ? P.primary : shade(P.primary, -0.25);
  const darkS = opts.flat ? P.secondary : shade(P.secondary, -0.2);

  // ami high-damage heat shimmer
  if (!opts.flat && (f.charging || p.glow > 0)) {
    const gx = p.frontHand.x;
    glowCircle(ctx, gx, p.frontHand.y, 26, P.glow, 0.18 + p.glow * 0.2);
  }

  // back leg
  const hipBack = { x: -hipW * 0.18, y: p.hipY + 1 };
  limb2(ctx, hipBack.x, hipBack.y, p.backFoot.x, p.backFoot.y - 4, p.legBendB * 0.8, -0.02, legW, darkS, outline);
  boot(ctx, p.backFoot.x, p.backFoot.y, P, darkS, outline, -1, opts);

  // back arm
  const shoulderBack = { x: -shoulderW * 0.28, y: p.shoulderY + 3 };
  limb2(ctx, shoulderBack.x, shoulderBack.y, p.backHand.x, p.backHand.y, p.armBendB, 0.02, armW * 0.92, darkP, outline);
  hand(ctx, p.backHand.x, p.backHand.y, 4.6 * bulk, P, id, darkP, outline, opts);

  // torso
  drawTorso(ctx, p, P, hipW, shoulderW, outline, id, opts);
  if (!opts.flat) drawEmblem(ctx, id, p, P);

  // front leg
  const hipFront = { x: hipW * 0.2, y: p.hipY + 1 };
  limb2(ctx, hipFront.x, hipFront.y, p.frontFoot.x, p.frontFoot.y - 4, p.legBendF * 0.8, 0.02, legW, P.secondary, outline);
  boot(ctx, p.frontFoot.x, p.frontFoot.y, P, P.secondary, outline, 1, opts);

  // head + hair/back accessories
  drawHeadBack(ctx, id, p, P, outline, opts);
  drawHead(ctx, id, p, P, outline, opts);
  drawHeadFront(ctx, id, p, P, outline, opts, f);

  // front arm
  const shoulderFront = { x: shoulderW * 0.26, y: p.shoulderY + 2 };
  limb2(ctx, shoulderFront.x, shoulderFront.y, p.frontHand.x, p.frontHand.y, p.armBendF, 0.03, armW, P.primary, outline);
  hand(ctx, p.frontHand.x, p.frontHand.y, 4.9 * bulk, P, id, P.primary, outline, opts);

  // accessories that move (scarves, flames)
  drawAccessory(ctx, id, p, P, f, outline, opts);
}

function drawTorso(ctx, p, P, hipW, shoulderW, outline, id, opts) {
  const topY = p.shoulderY;
  const botY = p.hipY;
  ctx.beginPath();
  ctx.moveTo(-hipW * 0.5, botY);
  ctx.quadraticCurveTo(-hipW * 0.62, botY - 9, -shoulderW * 0.46, topY + 5);
  ctx.quadraticCurveTo(-shoulderW * 0.5, topY - 2, -shoulderW * 0.24, topY - 3);
  ctx.quadraticCurveTo(0, topY - 6, shoulderW * 0.24, topY - 3);
  ctx.quadraticCurveTo(shoulderW * 0.5, topY - 2, shoulderW * 0.46, topY + 5);
  ctx.quadraticCurveTo(hipW * 0.62, botY - 9, hipW * 0.5, botY);
  ctx.closePath();
  const grad = ctx.createLinearGradient(-shoulderW / 2, topY, shoulderW / 2, botY);
  grad.addColorStop(0, opts.flat ? P.primary : mix(P.primary, '#ffffff', 0.16));
  grad.addColorStop(1, opts.flat ? P.primary : shade(P.primary, -0.18));
  ctx.fillStyle = grad;
  ctx.fill();
  if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 2.2; ctx.stroke(); }

  if (!opts.flat) {
    // belt / waist trim
    ctx.fillStyle = P.trim;
    roundRect(ctx, -hipW * 0.55, botY - 5, hipW * 1.1, 5, 2);
    ctx.fill();
    if (id === 'glacier') {
      // chest plate
      ctx.fillStyle = hexA('#e8fbff', 0.5);
      ctx.beginPath();
      ctx.moveTo(-shoulderW * 0.32, topY + 8);
      ctx.lineTo(0, topY + 2);
      ctx.lineTo(shoulderW * 0.32, topY + 8);
      ctx.lineTo(shoulderW * 0.2, topY + 24);
      ctx.lineTo(-shoulderW * 0.2, topY + 24);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = hexA('#ffffff', 0.6); ctx.lineWidth = 1; ctx.stroke();
    } else if (id === 'volt') {
      ctx.strokeStyle = P.trim;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(-shoulderW * 0.34, topY + 9);
      ctx.lineTo(shoulderW * 0.3, topY + 20);
      ctx.stroke();
    } else if (id === 'sprout') {
      // leaf collar
      ctx.fillStyle = shade(P.primary, 0.18);
      for (const s of [-1, 1]) {
        ctx.beginPath();
        ctx.ellipse(s * shoulderW * 0.28, topY + 4, 9, 4.5, s * 0.5, 0, TAU);
        ctx.fill();
      }
    }
  }
}

function drawEmblem(ctx, id, p, P) {
  const x = 0;
  const y = p.shoulderY + 17;
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = P.trim;
  ctx.strokeStyle = hexA('#000000', 0.2);
  ctx.lineWidth = 1;
  if (id === 'blaze') {
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.quadraticCurveTo(6, -2, 3, 4);
    ctx.quadraticCurveTo(0, 7, -3, 3);
    ctx.quadraticCurveTo(-6, -2, 0, -7);
    ctx.fill();
  } else if (id === 'volt') {
    poly(ctx, [[1, -8], [-5, 1], [-1, 1], [-2, 8], [5, -1], [1, -1]]);
    ctx.fill();
  } else if (id === 'glacier') {
    ctx.strokeStyle = P.trim;
    ctx.lineWidth = 1.6;
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * Math.PI;
      ctx.beginPath();
      ctx.moveTo(-Math.cos(a) * 6, -Math.sin(a) * 6);
      ctx.lineTo(Math.cos(a) * 6, Math.sin(a) * 6);
      ctx.stroke();
    }
  } else {
    ctx.beginPath();
    ctx.ellipse(0, 0, 6, 3.5, 0.5, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = P.trim;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-4, 2); ctx.lineTo(4, -2);
    ctx.stroke();
  }
  ctx.restore();
}

function hand(ctx, x, y, r, P, id, armColor, outline, opts) {
  ctx.fillStyle = id === 'glacier' ? shade(P.skin, 0.1) : (id === 'sprout' ? P.primary : P.skin);
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
  if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 1.6; ctx.stroke(); }
  if (id === 'glacier' && !opts.flat) {
    ctx.fillStyle = hexA('#e9fbff', 0.35);
    ctx.beginPath(); ctx.arc(x - 1, y - 1, r * 0.5, 0, TAU); ctx.fill();
  }
}

function boot(ctx, x, y, P, legColor, outline, side, opts) {
  ctx.save();
  ctx.translate(x, y - 2);
  ctx.scale(side, 1);
  ctx.fillStyle = opts.flat ? P.primary : (P.trim && P.accent ? mix(P.secondary, P.trim, 0.25) : P.trim);
  roundRect(ctx, -6, -2, 16, 6, 3);
  ctx.fill();
  if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 1.5; ctx.stroke(); }
  ctx.restore();
}

function drawHeadBack(ctx, id, p, P, outline, opts) {
  const hx = p.headX;
  const hy = p.headY;
  const r = p.headR;
  if (id === 'blaze') {
    // spiky hair silhouette
    ctx.save();
    ctx.translate(hx, hy);
    poly(ctx, [
      [-r - 2, 2], [-r - 5, -8], [-r + 1, -6], [-2, -r - 13],
      [5, -r - 5], [12, -r - 11], [12, -r + 1], [r + 4, -3],
      [r + 1, 8], [8, 10], [0, 7],
    ]);
    ctx.fillStyle = opts.flat ? P.primary : P.hair;
    ctx.fill();
    if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 2; ctx.stroke(); }
    // headband tails
    ctx.strokeStyle = opts.flat ? P.primary : P.trim;
    ctx.lineWidth = 3.4;
    ctx.lineCap = 'round';
    const w = Math.sin((p.bob + 2) * 0.5) * 2;
    ctx.beginPath();
    ctx.moveTo(-r + 1, -1);
    ctx.quadraticCurveTo(-r - 11, 4 + w, -r - 18, 12 + w);
    ctx.moveTo(-r + 1, 1);
    ctx.quadraticCurveTo(-r - 9, 9 + w, -r - 14, 17 + w);
    ctx.stroke();
    ctx.restore();
  } else if (id === 'volt') {
    // scarf behind
    ctx.save();
    ctx.strokeStyle = opts.flat ? P.primary : P.trim;
    ctx.lineCap = 'round';
    const wave = Math.sin((p.bob + 1) * 0.8) * 3;
    for (let i = 0; i < 2; i++) {
      ctx.lineWidth = 5 - i * 1.5;
      ctx.beginPath();
      ctx.moveTo(hx - 6, hy + 16 + i * 2);
      ctx.bezierCurveTo(hx - 22, hy + 16 + wave, hx - 28, hy + 26 - wave, hx - 40 - i * 4, hy + 24 + wave);
      ctx.stroke();
    }
    ctx.restore();
  } else if (id === 'glacier') {
    // horns
    ctx.save();
    ctx.translate(hx, hy);
    for (const s of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(s * (r - 2), -r + 2);
      ctx.quadraticCurveTo(s * (r + 7), -r - 5, s * (r + 5), -r - 14);
      ctx.quadraticCurveTo(s * (r + 1), -r - 5, s * (r - 6), -r + 4);
      ctx.closePath();
      ctx.fillStyle = opts.flat ? P.primary : '#e8f7ff';
      ctx.fill();
      if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 1.6; ctx.stroke(); }
    }
    ctx.restore();
  } else if (id === 'sprout') {
    // leaf crown
    ctx.save();
    ctx.translate(hx, hy);
    ctx.rotate(Math.sin((p.bob + 4) * 0.15) * 0.04);
    for (const [s, a, l] of [[-1, -0.9, 13], [1, -0.6, 15], [0, -1.5, 11]]) {
      ctx.save();
      ctx.rotate(a);
      ctx.beginPath();
      ctx.ellipse(s * 4, -r - 5, l, 5, s * 0.2, 0, TAU);
      ctx.fillStyle = opts.flat ? P.primary : (s < 0 ? shade(P.primary, -0.12) : shade(P.primary, 0.12));
      ctx.fill();
      if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 1.4; ctx.stroke(); }
      ctx.restore();
    }
    ctx.restore();
  }
}

function drawHead(ctx, id, p, P, outline, opts) {
  const hx = p.headX;
  const hy = p.headY;
  const r = p.headR;
  // neck
  ctx.fillStyle = opts.flat ? P.primary : shade(P.skin, -0.12);
  roundRect(ctx, hx - 4, hy + r - 3, 8, 8, 3);
  ctx.fill();

  ctx.save();
  ctx.translate(hx, hy);
  if (p.headTilt) ctx.rotate(p.headTilt);
  // face base
  if (id === 'glacier') {
    ctx.fillStyle = opts.flat ? P.primary : '#dff4ff';
    ctx.beginPath();
    ctx.moveTo(-r, 2);
    ctx.quadraticCurveTo(-r - 2, -r - 2, 0, -r - 3);
    ctx.quadraticCurveTo(r + 2, -r - 2, r, 2);
    ctx.quadraticCurveTo(r * 0.7, r + 6, 0, r + 7);
    ctx.quadraticCurveTo(-r * 0.7, r + 6, -r, 2);
    ctx.fill();
    if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 2; ctx.stroke(); }
    // helmet band
    ctx.fillStyle = opts.flat ? P.primary : P.secondary;
    roundRect(ctx, -r - 1, -r - 2, r * 2 + 2, 7, 3);
    ctx.fill();
  } else {
    ctx.fillStyle = opts.flat ? P.primary : P.skin;
    ctx.beginPath();
    ctx.ellipse(0, 0, r, r * 1.02, 0, 0, TAU);
    ctx.fill();
    if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 2; ctx.stroke(); }
  }

  // eyes
  if (id === 'volt') {
    // mask
    ctx.fillStyle = opts.flat ? P.primary : P.secondary;
    ctx.beginPath();
    ctx.ellipse(0, 5, r, r * 0.72, 0, 0, Math.PI);
    ctx.fill();
    ctx.fillStyle = opts.flat ? '#fff' : '#9ff4ff';
    ctx.shadowColor = '#45e3ff'; ctx.shadowBlur = 7;
    for (const ex of [-5.5, 5.5]) {
      ctx.beginPath();
      ctx.ellipse(ex, -2, 3.2, 1.7, -0.15, 0, TAU);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
  } else if (id === 'glacier') {
    ctx.fillStyle = opts.flat ? '#fff' : '#7fe6ff';
    ctx.shadowColor = '#7fe6ff'; ctx.shadowBlur = 8;
    for (const ex of [-5.5, 5.5]) {
      ctx.beginPath();
      ctx.ellipse(ex, -1, 2.8, 2.1, 0, 0, TAU);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
    // ice beard
    ctx.fillStyle = opts.flat ? P.primary : '#eafaff';
    poly(ctx, [[-9, 8], [-5, 16], [-1, 9], [4, 17], [8, 8], [5, 13], [0, 7]]);
    ctx.fill();
  } else if (id === 'sprout') {
    for (const ex of [-5.5, 5.5]) {
      ctx.fillStyle = opts.flat ? '#fff' : '#142018';
      ctx.beginPath(); ctx.ellipse(ex, -1, 3.1, 3.9, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(ex + 1.2, -2.6, 1.15, 0, TAU); ctx.fill();
    }
    ctx.strokeStyle = '#284022'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.arc(0, 5, 3, 0.2, Math.PI - 0.2); ctx.stroke();
  } else {
    // blaze
    ctx.fillStyle = '#fff';
    for (const ex of [-5.5, 5.5]) {
      ctx.beginPath(); ctx.ellipse(ex, -1, 3, 3.8, 0, 0, TAU); ctx.fill();
    }
    ctx.fillStyle = opts.flat ? '#000' : '#2a1720';
    for (const ex of [-5.5, 5.5]) {
      ctx.beginPath(); ctx.arc(ex + 1.1, -0.6, 1.5, 0, TAU); ctx.fill();
    }
    ctx.strokeStyle = opts.flat ? '#000' : P.hair;
    ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(-8.5, -6); ctx.lineTo(-3, -7.4); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(3, -7.4); ctx.lineTo(8.5, -6); ctx.stroke();
    ctx.strokeStyle = opts.flat ? '#000' : '#7c3a2e';
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(1, 7); ctx.quadraticCurveTo(3.5, 5.4, 5.6, 7); ctx.stroke();
  }

  // headband / hat / flower front
  if (id === 'blaze') {
    ctx.strokeStyle = opts.flat ? '#fff' : P.trim;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(-r + 1, -r * 0.42);
    ctx.quadraticCurveTo(0, -r * 0.58, r - 1, -r * 0.45);
    ctx.stroke();
    ctx.fillStyle = opts.flat ? '#fff' : P.trim;
    ctx.beginPath(); ctx.arc(-r + 1, -r * 0.42, 1.6, 0, TAU); ctx.fill();
  } else if (id === 'sprout') {
    // flower petals
    ctx.fillStyle = opts.flat ? '#fff' : P.trim;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU - 0.6;
      ctx.beginPath();
      ctx.ellipse(Math.cos(a) * 7, -r - 1 + Math.sin(a) * 4, 5, 3, a, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = opts.flat ? '#fff' : '#ff9a4d';
    ctx.beginPath(); ctx.arc(0, -r - 1, 3.2, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

function drawHeadFront() {}

function drawAccessory(ctx, id, p, P, f, outline, opts) {
  if (id === 'blaze') {
    const flame = (p.glow > 0.2 || f.charging) && !opts.flat;
    if (flame) {
      drawFlame(ctx, p.frontHand.x + 3, p.frontHand.y - 4, 16 + Math.sin(p.bob * 2) * 2, P);
      drawFlame(ctx, p.backHand.x, p.backHand.y - 3, 10, P);
    }
  } else if (id === 'volt') {
    if ((p.glow > 0.2 || f.charging) && !opts.flat) {
      ctx.strokeStyle = P.glow;
      ctx.lineWidth = 1.8;
      ctx.globalAlpha = 0.8;
      for (let i = 0; i < 2; i++) {
        const hx = i ? p.backHand : p.frontHand;
        ctx.beginPath();
        ctx.moveTo(hx.x - 8, hx.y - 7);
        ctx.lineTo(hx.x - 2, hx.y - 2);
        ctx.lineTo(hx.x - 6, hx.y + 2);
        ctx.lineTo(hx.x + 3, hx.y + 8);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }
  } else if (id === 'glacier') {
    if (!opts.flat) {
      // frost mist
      const t = (f.animTime || 0) * 0.05;
      ctx.fillStyle = hexA('#bff4ff', 0.16);
      for (let i = 0; i < 3; i++) {
        const x = p.headX - 16 - i * 5 - Math.sin(t + i) * 3;
        const y = p.headY + 8 + Math.sin(t * 1.3 + i) * 3;
        ctx.beginPath(); ctx.arc(x, y, 4 - i * 0.7, 0, TAU); ctx.fill();
      }
    }
  } else if (id === 'sprout') {
    if (!opts.flat && (p.glow > 0.3 || f.charging)) {
      ctx.fillStyle = hexA(P.trim, 0.85);
      for (let i = 0; i < 3; i++) {
        const a = (f.animTime * 0.07 + i * 2.1);
        ctx.beginPath();
        ctx.ellipse(p.frontHand.x + Math.cos(a) * 9, p.frontHand.y + Math.sin(a) * 7, 4, 2, a, 0, TAU);
        ctx.fill();
      }
    }
  }
}

function drawFlame(ctx, x, y, size, P) {
  ctx.save();
  ctx.translate(x, y);
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 3; i++) {
    const s = size * (1 - i * 0.24);
    ctx.fillStyle = hexA(i === 0 ? P.glow : i === 1 ? '#ffb347' : '#fff1b8', 0.55 - i * 0.12);
    ctx.beginPath();
    ctx.moveTo(0, s);
    ctx.quadraticCurveTo(-s * 0.7, s * 0.15, -s * 0.12, -s);
    ctx.quadraticCurveTo(0, -s * 0.3, s * 0.5, -s * 0.3);
    ctx.quadraticCurveTo(s * 0.6, s * 0.3, 0, s);
    ctx.fill();
  }
  ctx.restore();
}

export function drawFighterShadow(ctx, f, groundY, scale = 1) {
  if (!f || f.invisible) return;
  const dist = Math.max(0, groundY - f.y);
  const a = clamp(0.34 - dist / 900, 0.05, 0.34);
  const w = (34 - Math.min(16, dist / 28)) * (f.char?.physics.size || 1);
  const g = ctx.createRadialGradient(f.x, groundY + 2, 1, f.x, groundY + 2, Math.max(8, w));
  g.addColorStop(0, `rgba(0,0,0,${a})`);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(f.x, groundY + 3, Math.max(8, w), Math.max(3, w * 0.32), 0, 0, TAU);
  ctx.fill();
}

// ---------------------------------------------------------------------------
// Portrait / avatar rendering
// ---------------------------------------------------------------------------
export function drawCharacterCard(canvas, charId) {
  const char = CHAR_MAP[charId];
  if (!char) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = canvas.clientWidth || 260;
  const h = canvas.clientHeight || 190;
  canvas.width = Math.max(2, Math.round(w * dpr));
  canvas.height = Math.max(2, Math.round(h * dpr));
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);

  const P = char.palette;
  const g = ctx.createRadialGradient(w * 0.5, h * 0.42, 4, w * 0.5, h * 0.5, h * 0.7);
  g.addColorStop(0, hexA(P.ui[0], 0.35));
  g.addColorStop(1, hexA(P.ui[1], 0));
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = hexA(P.ui[0], 0.28);
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.ellipse(w * 0.5, h * 0.58, w * (0.2 + i * 0.12), h * (0.08 + i * 0.05), 0, 0, TAU);
    ctx.stroke();
  }
  ctx.restore();

  const fake = {
    char, charId, x: w * 0.5, y: h * 0.9, facing: 1, vx: 0, vy: 0,
    grounded: true, action: null, move: null, animTime: 60 + (char.num * 17), slot: 0,
    damage: 0, invincible: 0, respawnGlow: 0, hitFlash: 0, hitstun: 0, charging: false,
    crouching: false, landSquash: 0, airDodgeUsed: false, trail: [], dodgeTimer: 0,
  };
  const scale = Math.min(w / 190, h / 175) * 1.5;
  ctx.save();
  ctx.translate(fake.x, fake.y);
  ctx.scale(scale, scale);
  ctx.translate(-fake.x, -fake.y);
  drawFighter(ctx, fake, 0);
  ctx.restore();
}

export function drawAvatar(canvas, charId) {
  const char = CHAR_MAP[charId];
  if (!char) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const size = canvas.clientWidth || 64;
  canvas.width = Math.round(size * dpr);
  canvas.height = Math.round(size * dpr);
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, size, size);
  const P = char.palette;
  const g = ctx.createLinearGradient(0, 0, size, size);
  g.addColorStop(0, hexA(P.ui[0], 0.55));
  g.addColorStop(1, hexA(P.ui[1], 0.3));
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const fake = {
    char, x: size * 0.5, y: size * 1.0, facing: 1, vx: 0, vy: 0,
    grounded: true, action: null, animTime: 40, slot: 0, damage: 0,
    invincible: 0, respawnGlow: 0, hitFlash: 0, hitstun: 0, charging: false,
    crouching: false, landSquash: 0, airDodgeUsed: false, trail: [],
  };
  const scale = size / 135;
  ctx.save();
  ctx.translate(fake.x, fake.y);
  ctx.scale(scale, scale);
  ctx.translate(-fake.x, -fake.y);
  drawFighter(ctx, fake, 0);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Backdrop — skies, parallax, platforms and stage thumbnails.
// ---------------------------------------------------------------------------
import { CHAR_MAP, STAGE_MAP } from './data.js';
import {
  TAU, clamp, hexA, mix, shade, poly, roundRect, glowCircle,
} from './draw-utils.js';
import { drawFighter } from './figure.js';

function ridge(ctx, w, base, amp, color, seed, scroll, step = 46) {
  ctx.beginPath();
  ctx.moveTo(-80, base + 400);
  for (let x = -80; x <= w + 80; x += step) {
    const sx = x + scroll;
    const y = base
      - amp * (0.55 + 0.3 * Math.sin(sx * 0.008 + seed) + 0.15 * Math.sin(sx * 0.021 + seed * 2.3))
      - amp * 0.12 * Math.sin(sx * 0.05 + seed * 4);
    ctx.lineTo(x, y);
  }
  ctx.lineTo(w + 80, base + 400);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
}

function peaks(ctx, w, base, amp, color, snow, seed, scroll) {
  const pts = [];
  const spacing = 150;
  for (let i = -2; i < Math.ceil(w / spacing) + 3; i++) {
    const x = i * spacing + ((scroll + seed * 41) % spacing);
    const h = amp * (0.55 + 0.45 * Math.abs(Math.sin(i * 1.7 + seed)));
    pts.push([x - spacing * 0.62, base, x, base - h, x + spacing * 0.55, base]);
  }
  ctx.fillStyle = color;
  for (const [x1, y1, x2, y2, x3, y3] of pts) {
    poly(ctx, [[x1, y1], [x2, y2], [x3, y3]]);
    ctx.fill();
    // snow cap
    const sy = y2 + (y1 - y2) * 0.24;
    const sx = x2 + (x3 - x2) * 0.22;
    const lx = x2 + (x1 - x2) * 0.22;
    ctx.fillStyle = snow;
    poly(ctx, [[x2, y2], [sx, sy], [x2 + (sx - x2) * 0.15, sy + 10], [lx, sy], [x2 + (lx - x2) * 0.2, sy + 7]]);
    ctx.fill();
    ctx.fillStyle = color;
  }
}

function cloud(ctx, x, y, s, alpha, color = '#fff') {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.ellipse(x, y, 42 * s, 14 * s, 0, 0, TAU);
  ctx.ellipse(x - 30 * s, y + 2 * s, 26 * s, 10 * s, 0, 0, TAU);
  ctx.ellipse(x + 32 * s, y + 1 * s, 30 * s, 11 * s, 0, 0, TAU);
  ctx.ellipse(x + 4 * s, y - 8 * s, 24 * s, 14 * s, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawBackground(ctx, view, stage, cam, time) {
  const w = view.w;
  const h = view.h;
  const sky = stage.sky;
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, sky[0]);
  grad.addColorStop(0.38, sky[1]);
  grad.addColorStop(0.72, sky[2]);
  grad.addColorStop(1, sky[3]);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  const camX = cam.x || 0;
  const camY = cam.y || 0;
  const horizon = h * 0.64;
  const scale = h / 720;

  // stars (sky + frost)
  if (stage.kind !== 'ember') {
    ctx.save();
    for (let i = 0; i < 52; i++) {
      const sx = ((i * 137.5) % 1) * 0 + ((i * 197.13) % w);
      const sy = ((i * 89.7) % (h * 0.52)) - 10;
      const tw = 0.35 + 0.65 * Math.abs(Math.sin(time * 0.0012 + i));
      ctx.globalAlpha = tw * (stage.kind === 'frost' ? 0.7 : 0.5);
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(sx - camX * 0.01, sy, (i % 5 === 0 ? 1.7 : 0.9) * scale, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  // sun / moon / furnace glow
  if (stage.kind === 'sky') {
    const sx = w * 0.72 - camX * 0.02;
    const sy = h * 0.34;
    const r = Math.min(w, h) * 0.14;
    const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, r * 2.2);
    g.addColorStop(0, 'rgba(255,226,170,0.55)');
    g.addColorStop(0.25, 'rgba(255,170,110,0.24)');
    g.addColorStop(1, 'rgba(255,120,80,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    const sun = ctx.createLinearGradient(sx, sy - r, sx, sy + r);
    sun.addColorStop(0, '#fff2c8');
    sun.addColorStop(1, '#ffb26b');
    ctx.fillStyle = sun;
    ctx.beginPath();
    ctx.arc(sx, sy, r * 0.62, 0, TAU);
    ctx.fill();
  } else if (stage.kind === 'frost') {
    const sx = w * 0.2 - camX * 0.015;
    const sy = h * 0.2;
    const r = Math.min(w, h) * 0.09;
    glowCircle(ctx, sx, sy, r * 2.6, '#a8e8ff', 0.22);
    ctx.fillStyle = '#e8fbff';
    ctx.beginPath(); ctx.arc(sx, sy, r * 0.55, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(140,180,210,0.35)';
    ctx.beginPath(); ctx.arc(sx - r * 0.18, sy - r * 0.12, r * 0.14, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(sx + r * 0.16, sy + r * 0.14, r * 0.1, 0, TAU); ctx.fill();

    // aurora ribbons
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 3; i++) {
      const y = h * (0.18 + i * 0.07);
      const g = ctx.createLinearGradient(0, y - 60, w, y + 60);
      g.addColorStop(0, hexA(stage.accent2, 0));
      g.addColorStop(0.35, hexA(stage.accent, 0.13 - i * 0.02));
      g.addColorStop(0.7, hexA(stage.accent2, 0.1 - i * 0.02));
      g.addColorStop(1, hexA(stage.accent, 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(0, y);
      for (let x = 0; x <= w; x += 40) {
        ctx.lineTo(x, y + Math.sin(x * 0.006 + time * 0.0007 + i * 1.8) * 26 + Math.sin(x * 0.014 + i) * 10);
      }
      for (let x = w; x >= 0; x -= 40) {
        ctx.lineTo(x, y + 46 + Math.sin(x * 0.005 + time * 0.0009 + i * 2.2) * 30);
      }
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  } else {
    // ember furnace haze
    const g = ctx.createRadialGradient(w * 0.5, h * 0.9, 20, w * 0.5, h * 0.9, w * 0.7);
    g.addColorStop(0, 'rgba(255,150,60,0.45)');
    g.addColorStop(0.4, 'rgba(200,50,30,0.18)');
    g.addColorStop(1, 'rgba(20,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }

  // distant clouds
  if (stage.kind === 'sky') {
    for (let i = 0; i < 7; i++) {
      const base = i * 337.7;
      const x = ((base + time * (0.008 + i * 0.002) - camX * 0.05) % (w + 400)) - 200;
      const y = h * (0.18 + ((i * 71) % 100) / 300);
      cloud(ctx, x, y, 0.8 + (i % 4) * 0.24, 0.06 + (i % 3) * 0.03, '#ffe2c4');
    }
  }

  // mountain layers
  const scroll = -camX * 0.08;
  if (stage.kind === 'sky') {
    ridge(ctx, w, horizon + 40, h * 0.22, hexA('#2a1a44', 0.55), 3.1, scroll * 0.4, 60);
    ridge(ctx, w, horizon + 70, h * 0.28, hexA('#241638', 0.8), 6.4, scroll * 0.8, 48);
    ridge(ctx, w, horizon + 120, h * 0.2, '#1a1028', 2.2, scroll * 1.2, 40);
  } else if (stage.kind === 'ember') {
    ridge(ctx, w, horizon + 30, h * 0.13, hexA('#2a0b10', 0.8), 4.8, -camX * 0.05, 70);
    // factory towers
    const scroll2 = -camX * 0.12;
    for (let i = 0; i < 9; i++) {
      const x = ((i * 173 + scroll2) % (w + 240)) - 120;
      const tw = 16 + (i % 4) * 11;
      const th = 50 + (i % 5) * 46;
      ctx.fillStyle = i % 2 ? '#1c080d' : '#250a10';
      ctx.fillRect(x, horizon - th, tw, th + 160);
      ctx.fillStyle = 'rgba(255,120,60,0.55)';
      for (let j = 0; j < 3; j++) {
        if ((i + j) % 3 === 0) ctx.fillRect(x + tw * 0.25, horizon - th + 14 + j * 19, tw * 0.5, 4);
      }
      ctx.fillStyle = 'rgba(255,180,100,0.25)';
      ctx.fillRect(x + tw * 0.5 - 2, horizon - th - 18, 4, 18);
    }
    // lava glow at the bottom
    const lg = ctx.createLinearGradient(0, h * 0.72, 0, h);
    lg.addColorStop(0, 'rgba(255,90,30,0)');
    lg.addColorStop(1, 'rgba(255,120,40,0.3)');
    ctx.fillStyle = lg;
    ctx.fillRect(0, h * 0.72, w, h * 0.28);
  } else {
    peaks(ctx, w, horizon + 50, h * 0.34, hexA('#102a44', 0.85), hexA('#c8e6f5', 0.75), 2.7, -camX * 0.05);
    peaks(ctx, w, horizon + 105, h * 0.24, hexA('#0b1d31', 0.95), hexA('#a9cfe2', 0.65), 5.9, -camX * 0.09);
  }

  // floating islands (sky)
  if (stage.kind === 'sky') {
    const spots = [
      [-0.05, 0.24, 1.25], [0.27, 0.5, 0.7], [0.86, 0.32, 1.05], [0.63, 0.52, 0.5],
    ];
    for (let i = 0; i < spots.length; i++) {
      const [fx, fy, s] = spots[i];
      const x = fx * w - camX * 0.14 * (i % 2 ? 1 : 0.6) + Math.sin(time * 0.0003 + i) * 5;
      const y = fy * h + Math.cos(time * 0.00025 + i) * 4;
      drawFloatingIsland(ctx, x, y, s * Math.min(1.5, w / 1200 + 0.5), stage, i);
    }
    for (let i = 0; i < 5; i++) {
      const x = ((i * 271 + time * 0.02 - camX * 0.03) % (w + 200)) - 100;
      const y = h * (0.2 + (i % 3) * 0.09);
      ctx.strokeStyle = 'rgba(40,20,45,0.55)';
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(x - 7, y);
      ctx.quadraticCurveTo(x - 2, y - 5, x + 3, y - 1);
      ctx.quadraticCurveTo(x + 7, y - 5, x + 12, y);
      ctx.stroke();
    }
  }

  // horizon haze
  const haze = ctx.createLinearGradient(0, horizon - 90, 0, horizon + 90);
  haze.addColorStop(0, 'rgba(255,255,255,0)');
  haze.addColorStop(0.5, hexA(stage.accent, stage.kind === 'ember' ? 0.12 : 0.16));
  haze.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = haze;
  ctx.fillRect(0, horizon - 90, w, 190);

  // rolling fog under the arena
  ctx.save();
  for (let i = 0; i < 4; i++) {
    const y = h * (0.72 + i * 0.07) + Math.sin(time * 0.0005 + i) * 4;
    const a = 0.05 + i * 0.02;
    const g = ctx.createLinearGradient(0, y - 26, 0, y + 30);
    g.addColorStop(0, 'rgba(255,255,255,0)');
    g.addColorStop(0.5, stage.kind === 'ember' ? `rgba(255,120,60,${a})` : `rgba(230,225,255,${a})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, y - 26, w, 60);
  }
  ctx.restore();
}

function drawFloatingIsland(ctx, x, y, s, stage, seed) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(s, s);
  ctx.fillStyle = 'rgba(40,24,60,0.85)';
  ctx.beginPath();
  ctx.moveTo(-64, 0);
  ctx.quadraticCurveTo(-40, -18, 0, -16);
  ctx.quadraticCurveTo(45, -17, 68, 0);
  ctx.lineTo(40, 16);
  ctx.lineTo(20, 30);
  ctx.lineTo(-2, 48);
  ctx.lineTo(-20, 26);
  ctx.lineTo(-44, 14);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = seed % 2 ? '#6a5a8f' : '#746294';
  ctx.beginPath();
  ctx.ellipse(0, -9, 68, 14, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,210,140,0.3)';
  ctx.beginPath(); ctx.ellipse(8, -15, 42, 5, 0, 0, TAU); ctx.fill();
  // trees
  ctx.fillStyle = '#2a1b35';
  for (let i = 0; i < 3; i++) {
    const tx = -36 + i * 30;
    ctx.fillRect(tx, -36, 3, 22);
    ctx.beginPath();
    ctx.moveTo(tx - 11, -34);
    ctx.lineTo(tx + 1.5, -54);
    ctx.lineTo(tx + 13, -34);
    ctx.fill();
  }
  // hanging crystal
  ctx.fillStyle = 'rgba(255,190,110,0.5)';
  ctx.beginPath();
  ctx.moveTo(-16, 34); ctx.lineTo(-9, 48); ctx.lineTo(-2, 32); ctx.closePath();
  ctx.fill();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Platforms
// ---------------------------------------------------------------------------
export function drawStage(ctx, stage, time, opts = {}) {
  const main = stage.platforms[0];
  drawArenaDecor(ctx, stage, time, opts);

  for (let i = 0; i < stage.platforms.length; i++) {
    const p = stage.platforms[i];
    if (p.main) drawMainPlatform(ctx, p, stage, time, opts);
    else drawFloatPlatform(ctx, p, stage, time, opts, i);
  }
}

function drawArenaDecor(ctx, stage, time, opts) {
  const main = stage.platforms[0];
  const half = main.w / 2;
  if (stage.kind === 'sky') {
    // ruined pillars behind the deck
    for (const side of [-1, 1]) {
      const x = side * (half - 135);
      ctx.fillStyle = 'rgba(38,26,58,0.9)';
      ctx.fillRect(x - 15, -215, 30, 216);
      ctx.fillStyle = 'rgba(94,74,130,0.85)';
      ctx.fillRect(x - 20, -223, 40, 14);
      ctx.fillRect(x - 19, -148, 38, 8);
      ctx.fillStyle = 'rgba(255,196,120,0.25)';
      ctx.fillRect(x - 3, -205, 6, 58);
      // hanging banner
      ctx.fillStyle = hexA(stage.accent, 0.4);
      ctx.beginPath();
      ctx.moveTo(x + side * 10, -200);
      ctx.lineTo(x + side * 10, -155);
      ctx.lineTo(x + side * 22, -168);
      ctx.closePath();
      ctx.fill();
    }
    // central sigil on the floor
    ctx.save();
    ctx.translate(0, 2);
    ctx.scale(1, 0.2);
    ctx.strokeStyle = hexA(stage.accent, 0.3);
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 92, 0, TAU); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 73, 0, TAU); ctx.stroke();
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 74, Math.sin(a) * 74);
      ctx.lineTo(Math.cos(a) * 91, Math.sin(a) * 91);
      ctx.stroke();
    }
    ctx.restore();
  } else if (stage.kind === 'ember') {
    // rear pipes + furnace mouths
    for (const side of [-1, 1]) {
      const x = side * (half - 100);
      ctx.fillStyle = '#1b0a10';
      ctx.fillRect(x - 22, -188, 44, 190);
      ctx.fillStyle = '#2e1118';
      ctx.fillRect(x - 30, -196, 60, 18);
      ctx.fillStyle = 'rgba(255,120,50,0.55)';
      for (let i = 0; i < 3; i++) ctx.fillRect(x - 13, -165 + i * 34, 26, 9);
      ctx.fillStyle = 'rgba(255,160,80,0.12)';
      ctx.beginPath(); ctx.arc(x, -150, 48, 0, TAU); ctx.fill();
    }
    // central furnace glyph
    ctx.save();
    ctx.translate(0, 10);
    ctx.fillStyle = 'rgba(255,120,45,0.1)';
    ctx.fillRect(-140, 20, 280, 24);
    ctx.strokeStyle = 'rgba(255,150,70,0.32)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-70, 28); ctx.lineTo(-34, 28); ctx.lineTo(-22, 14); ctx.lineTo(22, 14);
    ctx.lineTo(34, 28); ctx.lineTo(70, 28);
    ctx.stroke();
    ctx.restore();
  } else {
    // ice crystals and snow drifts
    for (const side of [-1, 1]) {
      const x = side * (half - 120);
      ctx.fillStyle = 'rgba(130,200,225,0.22)';
      ctx.beginPath();
      ctx.moveTo(x - 34, 4);
      ctx.lineTo(x - 8, -100 - Math.abs(side) * 20);
      ctx.lineTo(x + 4, -42);
      ctx.lineTo(x + 18, -78);
      ctx.lineTo(x + 36, 4);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(220,250,255,0.3)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }
    // frozen sigil
    ctx.save();
    ctx.translate(0, 3);
    ctx.scale(1, 0.22);
    ctx.strokeStyle = 'rgba(150,240,255,0.3)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 40, Math.sin(a) * 40);
      ctx.lineTo(Math.cos(a + 0.5) * 86, Math.sin(a + 0.5) * 86);
      ctx.stroke();
    }
    ctx.restore();
  }
}

function drawMainPlatform(ctx, p, stage, time, opts) {
  const x = p.x - p.w / 2;
  const y = p.y;
  const h = p.h;
  const accent = stage.accent;

  // contact shadow
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  roundRect(ctx, x + 6, y + 10, p.w, h + 20, 16);
  ctx.fill();
  ctx.restore();

  // main slab
  const grad = ctx.createLinearGradient(0, y, 0, y + h);
  grad.addColorStop(0, stage.platform.top);
  grad.addColorStop(0.45, stage.platform.top2);
  grad.addColorStop(1, stage.platform.side);
  ctx.fillStyle = grad;
  roundRect(ctx, x, y, p.w, h, 10);
  ctx.fill();

  // top light
  const topLight = ctx.createLinearGradient(0, y, 0, y + 9);
  topLight.addColorStop(0, hexA('#ffffff', 0.5));
  topLight.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = topLight;
  roundRect(ctx, x + 2, y, p.w - 4, 10, 5);
  ctx.fill();

  // glowing rim
  ctx.save();
  ctx.shadowColor = accent;
  ctx.shadowBlur = 18;
  ctx.strokeStyle = hexA(accent, 0.85);
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(x + 10, y + 1);
  ctx.lineTo(x + p.w - 10, y + 1);
  ctx.stroke();
  ctx.restore();

  // surface detail
  ctx.strokeStyle = hexA('#000000', 0.18);
  ctx.lineWidth = 1;
  for (let i = 1; i < 8; i++) {
    const tx = x + (p.w / 8) * i;
    ctx.beginPath();
    ctx.moveTo(tx, y + 12);
    ctx.lineTo(tx + (i % 2 ? -3 : 3), y + h - 6);
    ctx.stroke();
  }
  ctx.strokeStyle = hexA('#ffffff', 0.08);
  for (let i = 0; i < 5; i++) {
    const tx = x + 60 + i * (p.w / 5.4);
    ctx.beginPath();
    ctx.moveTo(tx, y + 6);
    ctx.lineTo(tx + 46, y + 6);
    ctx.stroke();
  }

  // underside
  const bottom = y + h;
  if (stage.kind === 'sky') {
    ctx.fillStyle = '#1a1229';
    ctx.beginPath();
    ctx.moveTo(x + 6, bottom - 2);
    ctx.lineTo(x + 30, bottom + 18);
    ctx.lineTo(x + 72, bottom + 30);
    ctx.lineTo(x + 120, bottom + 16);
    ctx.lineTo(x + 200, bottom + 42);
    ctx.lineTo(x + 300, bottom + 22);
    ctx.lineTo(x + 390, bottom + 50);
    ctx.lineTo(x + 470, bottom + 24);
    ctx.lineTo(x + 580, bottom + 44);
    ctx.lineTo(x + 670, bottom + 18);
    ctx.lineTo(x + 760, bottom + 38);
    ctx.lineTo(x + 860, bottom + 20);
    ctx.lineTo(x + 950, bottom + 46);
    ctx.lineTo(x + 1050, bottom + 24);
    ctx.lineTo(x + 1140, bottom + 36);
    ctx.lineTo(x + p.w - 6, bottom - 2);
    ctx.closePath();
    ctx.fill();
    // vines
    ctx.strokeStyle = 'rgba(120,160,90,0.45)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 9; i++) {
      const vx = x + 70 + i * (p.w - 140) / 8;
      ctx.beginPath();
      ctx.moveTo(vx, bottom + 12);
      ctx.quadraticCurveTo(vx + 4, bottom + 28, vx - 5, bottom + 40 + (i % 3) * 8);
      ctx.stroke();
    }
  } else if (stage.kind === 'ember') {
    ctx.fillStyle = '#18090e';
    ctx.fillRect(x + 10, bottom - 4, p.w - 20, 34);
    ctx.strokeStyle = 'rgba(255,120,55,0.55)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(x + 30, bottom + 18);
    ctx.lineTo(x + p.w - 30, bottom + 18);
    ctx.stroke();
    for (let i = 0; i < 6; i++) {
      const vx = x + 100 + i * (p.w - 200) / 5;
      ctx.fillStyle = 'rgba(255,120,50,0.65)';
      ctx.beginPath(); ctx.arc(vx, bottom + 18, 4, 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(255,190,90,0.12)';
      ctx.beginPath(); ctx.arc(vx, bottom + 18, 16, 0, TAU); ctx.fill();
    }
  } else {
    ctx.fillStyle = '#101f31';
    ctx.beginPath();
    ctx.moveTo(x + 6, bottom - 2);
    ctx.lineTo(x + p.w - 6, bottom - 2);
    ctx.lineTo(x + p.w - 6, bottom + 16);
    ctx.lineTo(x + 900, bottom + 26);
    ctx.lineTo(x + 760, bottom + 46);
    ctx.lineTo(x + 640, bottom + 28);
    ctx.lineTo(x + 520, bottom + 52);
    ctx.lineTo(x + 400, bottom + 30);
    ctx.lineTo(x + 300, bottom + 44);
    ctx.lineTo(x + 180, bottom + 27);
    ctx.lineTo(x + 90, bottom + 34);
    ctx.lineTo(x + 24, bottom + 18);
    ctx.closePath();
    ctx.fill();
  }

  // edge cap lights
  ctx.fillStyle = hexA(accent, 0.55);
  roundRect(ctx, x + p.w - 12, y + h * 0.22, 5, h * 0.4, 3);
  ctx.fill();
  roundRect(ctx, x + 7, y + h * 0.22, 5, h * 0.4, 3);
  ctx.fill();
}

function drawFloatPlatform(ctx, p, stage, time, opts, idx) {
  const x = p.x - p.w / 2;
  const y = p.y;
  const h = Math.max(20, p.h + 6);
  const accent = stage.accent;

  // soft glow underneath
  glowCircle(ctx, p.x, y + h, p.w * 0.32, accent, 0.1);

  const grad = ctx.createLinearGradient(0, y, 0, y + h);
  grad.addColorStop(0, stage.platform.top);
  grad.addColorStop(0.55, stage.platform.top2);
  grad.addColorStop(1, stage.platform.side);
  ctx.fillStyle = grad;
  roundRect(ctx, x, y, p.w, h, h / 2);
  ctx.fill();

  const topLight = ctx.createLinearGradient(0, y, 0, y + 7);
  topLight.addColorStop(0, 'rgba(255,255,255,0.5)');
  topLight.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = topLight;
  roundRect(ctx, x + 3, y, p.w - 6, 8, 4);
  ctx.fill();

  ctx.save();
  ctx.shadowColor = accent;
  ctx.shadowBlur = 14;
  ctx.strokeStyle = hexA(accent, 0.82);
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x + 12, y + 1);
  ctx.lineTo(x + p.w - 12, y + 1);
  ctx.stroke();
  ctx.restore();

  ctx.strokeStyle = hexA('#000000', 0.16);
  ctx.lineWidth = 1;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(x + 20 + i * (p.w - 40) / 4, y + 6);
    ctx.lineTo(x + 20 + i * (p.w - 40) / 4, y + h - 4);
    ctx.stroke();
  }

  // hanging ornaments
  if (stage.kind === 'sky') {
    ctx.strokeStyle = 'rgba(255,210,140,0.3)';
    ctx.lineWidth = 1.5;
    for (const s of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(p.x + s * p.w * 0.34, y + h);
      ctx.lineTo(p.x + s * p.w * 0.3, y + h + 20);
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,190,100,0.65)';
      ctx.beginPath();
      ctx.moveTo(p.x + s * p.w * 0.3 - 3, y + h + 20);
      ctx.lineTo(p.x + s * p.w * 0.3 + 3, y + h + 20);
      ctx.lineTo(p.x + s * p.w * 0.3, y + h + 30);
      ctx.closePath();
      ctx.fill();
    }
  } else if (stage.kind === 'ember') {
    ctx.fillStyle = 'rgba(255,120,50,0.65)';
    for (let i = 0; i < 3; i++) {
      const lx = p.x + (i - 1) * p.w * 0.26;
      ctx.beginPath(); ctx.arc(lx, y + h + 5, 3, 0, TAU); ctx.fill();
    }
  } else {
    ctx.fillStyle = 'rgba(190,240,255,0.5)';
    for (const s of [-1, 1]) {
      const ix = p.x + s * p.w * 0.3;
      ctx.beginPath();
      ctx.moveTo(ix - 4, y + h); ctx.lineTo(ix + 4, y + h); ctx.lineTo(ix, y + h + 18);
      ctx.closePath(); ctx.fill();
    }
  }
}

// ---------------------------------------------------------------------------
// Ambient menu particles
// ---------------------------------------------------------------------------
export function drawAmbient(ctx, view, stage, time, intensity = 1) {
  const w = view.w;
  const h = view.h;
  if (stage.kind === 'ember') {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 46; i++) {
      const seed = i * 131.17;
      const x = ((seed + Math.sin(time * 0.0004 + i) * 35) % w + w) % w;
      const y = h - ((seed * 1.7 + time * (0.02 + (i % 5) * 0.004)) % h);
      const a = 0.25 + 0.5 * Math.abs(Math.sin(time * 0.002 + i));
      ctx.fillStyle = `rgba(255,${120 + (i % 6) * 12},60,${a * 0.6 * intensity})`;
      ctx.beginPath(); ctx.arc(x, y, (i % 3) + 1, 0, TAU); ctx.fill();
    }
    ctx.restore();
  } else if (stage.kind === 'frost') {
    ctx.save();
    for (let i = 0; i < 56; i++) {
      const seed = i * 173.7;
      const x = ((seed + Math.sin(time * 0.0005 + i) * 30) % w + w) % w;
      const y = ((seed * 2.3 + time * (0.01 + (i % 4) * 0.003)) % h);
      ctx.fillStyle = `rgba(235,250,255,${0.15 + (i % 4) * 0.08})`;
      ctx.beginPath(); ctx.arc(x, y, 1 + (i % 3) * 0.7, 0, TAU); ctx.fill();
    }
    ctx.restore();
  } else {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 30; i++) {
      const seed = i * 211.3;
      const x = ((seed + Math.sin(time * 0.0007 + i * 2) * 45) % w + w) % w;
      const y = ((seed * 1.4 + time * (0.008 + (i % 3) * 0.003)) % h);
      ctx.fillStyle = `rgba(255,215,150,${0.08 + (i % 5) * 0.025})`;
      ctx.beginPath(); ctx.arc(x, y, 1.2 + (i % 4) * 0.6, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }
}

// ---------------------------------------------------------------------------
// Stage preview
// ---------------------------------------------------------------------------
export function drawStageThumb(canvas, stageId) {
  const stage = STAGE_MAP[stageId];
  if (!stage) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = canvas.clientWidth || 420;
  const h = canvas.clientHeight || 236;
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const view = { w, h };
  const cam = { x: 0, y: -80, zoom: 0.9 };
  drawBackground(ctx, view, stage, cam, 1200);

  const scale = Math.min(w / 1480, h / 720) * 1.3;
  ctx.save();
  ctx.translate(w / 2, h * 0.66);
  ctx.scale(scale, scale);
  drawStage(ctx, stage, 1200, { thumb: true });

  // tiny fighters for scale
  const chars = ['blaze', 'volt'];
  chars.forEach((id, i) => {
    const char = CHAR_MAP[id];
    const fake = {
      char, charId: id, x: i ? 220 : -240, y: 0, facing: i ? -1 : 1,
      vx: 0, vy: 0, grounded: true, action: null, animTime: 50 + i * 10,
      slot: i, damage: 0, invincible: 0, respawnGlow: 0, hitFlash: 0,
      hitstun: 0, charging: false, crouching: false, landSquash: 0,
      airDodgeUsed: false, trail: [],
    };
    drawFighter(ctx, fake, 0);
  });
  ctx.restore();

  // bottom fade
  const fade = ctx.createLinearGradient(0, h * 0.7, 0, h);
  fade.addColorStop(0, 'rgba(8,7,16,0)');
  fade.addColorStop(1, 'rgba(8,7,16,0.5)');
  ctx.fillStyle = fade;
  ctx.fillRect(0, 0, w, h);
}

// ---------------------------------------------------------------------------
// Renderer — composes backdrop, stage, fighters, effects and banners.
// ---------------------------------------------------------------------------
import { CHAR_MAP, STAGE_MAP } from './data.js';
import {
  TAU, clamp, hexA, mix, roundRect, poly, starPath, glowCircle,
} from './draw-utils.js';
import { drawBackground, drawStage, drawAmbient } from './backdrop.js';
import { drawFighter, drawFighterShadow } from './figure.js';

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.view = { w: 1280, h: 720 };
    this.dpr = 1;
    this.menuFighters = null;
    this.menuStageId = null;
  }

  resize(w, h) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.dpr = dpr;
    this.view = { w: Math.max(320, w), h: Math.max(240, h) };
    this.canvas.width = Math.round(this.view.w * dpr);
    this.canvas.height = Math.round(this.view.h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.ctx.imageSmoothingEnabled = true;
  }

  // -------------------------------------------------------------------------
  renderGame(game, time) {
    const ctx = this.ctx;
    const { w, h } = this.view;
    ctx.clearRect(0, 0, w, h);
    if (!game.initialized) {
      this.renderMenu(game.stage.id, time, 'title');
      return;
    }

    const cam = game.camera;
    drawBackground(ctx, this.view, game.stage, cam, time);

    const base = h / 720;
    const scale = base * cam.zoom * (1 + (cam.punch || 0));
    const shakeX = game.shake > 0.2 ? (Math.random() * 2 - 1) * game.shake : 0;
    const shakeY = game.shake > 0.2 ? (Math.random() * 2 - 1) * game.shake : 0;
    const originX = w / 2 + shakeX;
    const originY = h * 0.60 + shakeY;

    ctx.save();
    ctx.translate(originX, originY);
    ctx.scale(scale, scale);
    ctx.translate(-cam.x, -cam.y);

    drawStage(ctx, game.stage, time);

    // shadows
    for (const f of game.fighters) {
      if (f.invisible) continue;
      const ground = this.groundUnder(f, game.stage);
      if (ground !== null) drawFighterShadow(ctx, f, ground);
    }

    // entities sorted by feet / y position
    const entities = [];
    for (const p of game.projectiles) entities.push({ y: p.y, kind: 'proj', p });
    for (const f of game.fighters) {
      if (!f.invisible) entities.push({ y: f.y, kind: 'fighter', f });
    }
    entities.sort((a, b) => a.y - b.y);

    for (const e of entities) {
      if (e.kind === 'fighter') {
        this.drawRespawnHalo(ctx, e.f, time);
        drawFighter(ctx, e.f, time);
        this.drawPlayerRing(ctx, e.f, time);
      } else {
        this.drawProjectile(ctx, e.p, time);
      }
    }

    this.drawParticles(ctx, game.particles, time);
    this.drawPopups(ctx, game.popups);
    ctx.restore();

    // screen-space ambience
    drawAmbient(ctx, this.view, game.stage, time, 0.75);

    this.drawScreenOverlays(ctx, game, time);
    this.drawOffscreenMarkers(ctx, game, originX, originY, scale);
    this.drawAnnouncement(ctx, game, time);

    if (game.phase === 'ended') this.drawResultsBackdrop(ctx);
  }

  // -------------------------------------------------------------------------
  renderMenu(stageId, time, mode = 'title') {
    const ctx = this.ctx;
    const { w, h } = this.view;
    const stage = STAGE_MAP[stageId] || STAGE_MAP.sky;
    ctx.clearRect(0, 0, w, h);
    const cam = { x: 0, y: -95, zoom: 0.9 };
    drawBackground(ctx, this.view, stage, cam, time);

    const base = h / 720;
    const scale = base * 0.93;
    const originX = w / 2;
    const originY = h * 0.64;

    ctx.save();
    ctx.translate(originX, originY);
    ctx.scale(scale, scale);
    ctx.translate(-cam.x, -cam.y);
    drawStage(ctx, stage, time);
    if (mode === 'title') {
      const fs = this.getMenuFighters(stage);
      const sorted = [...fs].sort((a, b) => a.y - b.y);
      for (const f of sorted) {
        if (!f.invisible) {
          const ground = this.groundUnder(f, stage);
          if (ground !== null) drawFighterShadow(ctx, f, ground);
        }
      }
      for (const f of fs) {
        drawFighter(ctx, f, time);
        this.drawPlayerRing(ctx, f, time, true);
      }
    } else {
      // quieter scene for menu screens: two silhouetted fighters far apart
      const fs = this.getMenuFighters(stage).slice(0, 2);
      for (const f of fs) {
        const ground = this.groundUnder(f, stage);
        if (ground !== null) drawFighterShadow(ctx, f, ground);
      }
      for (const f of fs) drawFighter(ctx, f, time, { fade: 0.6 });
    }
    ctx.restore();

    drawAmbient(ctx, this.view, stage, time, 0.55);

    const v = ctx.createRadialGradient(w * 0.5, h * 0.4, Math.min(w, h) * 0.25, w * 0.5, h * 0.5, Math.max(w, h) * 0.75);
    v.addColorStop(0, 'rgba(4,3,10,0)');
    v.addColorStop(1, 'rgba(4,3,10,0.6)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, w, h);

    if (mode === 'title') {
      const top = ctx.createLinearGradient(0, 0, 0, h * 0.45);
      top.addColorStop(0, 'rgba(5,4,11,0.55)');
      top.addColorStop(1, 'rgba(5,4,11,0)');
      ctx.fillStyle = top;
      ctx.fillRect(0, 0, w, h * 0.45);
      const bottom = ctx.createLinearGradient(0, h * 0.55, 0, h);
      bottom.addColorStop(0, 'rgba(5,4,11,0)');
      bottom.addColorStop(1, 'rgba(5,4,11,0.85)');
      ctx.fillStyle = bottom;
      ctx.fillRect(0, h * 0.55, w, h * 0.45);
    }
  }

  getMenuFighters(stage) {
    if (this.menuFighters && this.menuStageId === stage.id) return this.menuFighters;
    const ids = ['blaze', 'volt', 'glacier', 'sprout'];
    const xs = [-410, -145, 145, 410];
    this.menuFighters = ids.map((id, i) => ({
      char: CHAR_MAP[id],
      charId: id,
      x: xs[i],
      y: 0,
      facing: xs[i] < 0 ? 1 : -1,
      vx: 0,
      vy: 0,
      grounded: true,
      action: null,
      move: null,
      animTime: 60 + i * 33,
      slot: i,
      damage: 0,
      invincible: 0,
      respawnGlow: 0,
      hitFlash: 0,
      hitstun: 0,
      charging: false,
      crouching: false,
      landSquash: 0,
      airDodgeUsed: false,
      trail: [],
      dodgeTimer: 0,
    }));
    this.menuStageId = stage.id;
    return this.menuFighters;
  }

  groundUnder(f, stage) {
    let best = null;
    for (const p of stage.platforms) {
      const half = p.w / 2;
      if (f.x < p.x - half || f.x > p.x + half) continue;
      if (p.y < f.y - 2) continue;
      const d = p.y - f.y;
      if (d > 700) continue;
      if (best === null || p.y < best) best = p.y;
    }
    return best;
  }

  // -------------------------------------------------------------------------
  drawPlayerRing(ctx, f, time, menu = false) {
    if (!f.char || f.kind === 'cpu' && menu) return;
    const color = f.color || '#ff7a3d';
    const y = 1.5;
    ctx.save();
    ctx.globalAlpha = menu ? 0.45 : 0.7;
    ctx.strokeStyle = hexA(color, 0.8);
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(f.x, y, 24 * (f.char.physics.size || 1), 6, 0, 0, TAU);
    ctx.stroke();
    ctx.restore();
  }

  drawRespawnHalo(ctx, f, time) {
    if (!f.respawnGlow || f.respawnGlow <= 0) return;
    const a = Math.min(1, f.respawnGlow / 60);
    ctx.save();
    ctx.globalAlpha = a;
    glowCircle(ctx, f.x, f.y - 45, 70, f.color, 0.28);
    ctx.strokeStyle = hexA(f.color, 0.7);
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(f.x, f.y + 1, 34 + Math.sin(time * 0.1) * 4, 9, 0, 0, TAU);
    ctx.stroke();
    for (let i = 0; i < 3; i++) {
      const ang = time * 0.04 + (i * TAU) / 3;
      ctx.beginPath();
      ctx.arc(f.x + Math.cos(ang) * 34, f.y - 45 + Math.sin(ang) * 16, 2.2, 0, TAU);
      ctx.fillStyle = f.color;
      ctx.fill();
    }
    ctx.restore();
  }

  // -------------------------------------------------------------------------
  drawProjectile(ctx, p, time) {
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.globalCompositeOperation = 'lighter';
    if (p.kind === 'fireball') {
      glowCircle(ctx, 0, 0, p.r * 2.6, p.color, 0.4);
      const tail = -Math.sign(p.vx || 1) * 18;
      ctx.fillStyle = hexA('#ff7a3d', 0.35);
      ctx.beginPath();
      ctx.ellipse(tail, 0, 18, 7, 0, 0, TAU);
      ctx.fill();
      const g = ctx.createRadialGradient(0, 0, 1, 0, 0, p.r);
      g.addColorStop(0, '#fff8d8');
      g.addColorStop(0.45, '#ffc857');
      g.addColorStop(1, '#ff4d3d');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(0, 0, p.r, 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.beginPath(); ctx.arc(-2, -2, p.r * 0.3, 0, TAU); ctx.fill();
    } else if (p.kind === 'bolt') {
      glowCircle(ctx, 0, 0, p.r * 3.2, p.color, 0.45);
      ctx.strokeStyle = '#e8feff';
      ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.moveTo(-Math.sign(p.vx || 1) * 14, -3);
      ctx.lineTo(-4, 5); ctx.lineTo(0, -5); ctx.lineTo(6, 3); ctx.lineTo(12, -2);
      ctx.stroke();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(0, 0, p.r * 0.55, 0, TAU); ctx.fill();
    } else if (p.kind === 'ice') {
      glowCircle(ctx, 0, 0, p.r * 2.6, p.color, 0.35);
      ctx.rotate(p.rot || 0);
      ctx.fillStyle = '#dffaff';
      poly(ctx, [[0, -p.r * 1.6], [p.r * 0.85, 0], [0, p.r * 1.4], [-p.r * 0.85, 0]]);
      ctx.fill();
      ctx.strokeStyle = hexA('#ffffff', 0.8);
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = 'rgba(120,220,255,0.5)';
      poly(ctx, [[0, -p.r], [p.r * 0.45, 0], [0, p.r * 0.5], [-p.r * 0.45, 0]]);
      ctx.fill();
    } else {
      // seed
      glowCircle(ctx, 0, 0, p.r * 2.2, p.color, 0.3);
      ctx.rotate(p.rot || 0);
      ctx.fillStyle = '#7d5a32';
      ctx.beginPath(); ctx.ellipse(0, 0, p.r * 0.95, p.r * 1.1, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#4f9d3f';
      ctx.beginPath(); ctx.ellipse(p.r * 0.6, -p.r * 0.6, p.r * 0.9, p.r * 0.4, -0.7, 0, TAU); ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.25)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(-1, -1, p.r * 0.5, 0, TAU); ctx.stroke();
    }
    ctx.restore();
  }

  // -------------------------------------------------------------------------
  drawParticles(ctx, particles, time) {
    ctx.save();
    for (const p of particles) {
      const life = clamp(p.life / (p.maxLife || 1), 0, 1);
      if (p.type === 'spark') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = Math.max(1, p.size * life);
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - p.vx * 2.4, p.y - p.vy * 2.4);
        ctx.stroke();
      } else if (p.type === 'star') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life;
        ctx.fillStyle = p.color;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        starPath(ctx, p.size * 2.2 * (0.5 + life * 0.5), p.size * 0.6, 4);
        ctx.fill();
        ctx.restore();
      } else if (p.type === 'dust') {
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = life * 0.5;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(1, p.size * (0.6 + (1 - life) * 0.7)), 0, TAU);
        ctx.fill();
      } else if (p.type === 'ring') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life * 0.8;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = Math.max(1, 5 * life);
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, TAU);
        ctx.stroke();
      } else if (p.type === 'slash') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3 + life * 5;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (0.7 + (1 - life) * 0.5), p.rot - 0.8, p.rot + 0.8);
        ctx.stroke();
      } else if (p.type === 'beam') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life * 0.9;
        const w = p.size * (0.5 + (1 - life) * 0.8);
        const g = ctx.createLinearGradient(p.x - p.size, p.y, p.x + p.size, p.y);
        g.addColorStop(0, hexA(p.color, 0));
        g.addColorStop(0.5, hexA(p.color, 0.75));
        g.addColorStop(1, hexA(p.color, 0));
        ctx.fillStyle = g;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        ctx.fillRect(-p.size, -w / 2, p.size * 2, w);
        ctx.restore();
      } else if (p.type === 'trail') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life * 0.5;
        ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * life, 0, TAU); ctx.fill();
      } else if (p.type === 'charge') {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life;
        ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, TAU); ctx.fill();
      } else if (p.type === 'ghost') {
        const char = CHAR_MAP[p.char];
        if (!char) continue;
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = life * 0.22;
        ctx.fillStyle = p.color;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.scale(p.facing || 1, 1);
        ctx.beginPath();
        ctx.ellipse(0, -36, 17, 27, 0, 0, TAU);
        ctx.fill();
        ctx.beginPath(); ctx.arc(1, -78, 15, 0, TAU); ctx.fill();
        ctx.restore();
      } else if (p.type === 'confetti') {
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = Math.min(1, life * 2);
        ctx.fillStyle = p.color;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
        ctx.restore();
      }
    }
    ctx.restore();
  }

  drawPopups(ctx, popups) {
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (const p of popups) {
      const t = p.life / p.maxLife;
      const age = 1 - t;
      const scale = (0.55 + Math.min(0.45, age * 2.2)) * p.scale;
      const alpha = t > 0.35 ? 1 : t / 0.35;
      ctx.globalAlpha = alpha;
      ctx.font = `900 ${Math.round(20 * scale)}px "Arial Black", Impact, sans-serif`;
      ctx.lineWidth = 4;
      ctx.strokeStyle = 'rgba(16,8,24,0.85)';
      ctx.strokeText(p.text, p.x, p.y);
      ctx.fillStyle = p.color;
      ctx.fillText(p.text, p.x, p.y);
    }
    ctx.restore();
  }

  // -------------------------------------------------------------------------
  drawScreenOverlays(ctx, game, time) {
    const { w, h } = this.view;
    // top + bottom gradient for HUD legibility
    const top = ctx.createLinearGradient(0, 0, 0, Math.min(190, h * 0.26));
    top.addColorStop(0, 'rgba(5,4,11,0.55)');
    top.addColorStop(1, 'rgba(5,4,11,0)');
    ctx.fillStyle = top;
    ctx.fillRect(0, 0, w, Math.min(190, h * 0.26));

    const bottom = ctx.createLinearGradient(0, h * 0.78, 0, h);
    bottom.addColorStop(0, 'rgba(5,4,11,0)');
    bottom.addColorStop(1, 'rgba(5,4,11,0.45)');
    ctx.fillStyle = bottom;
    ctx.fillRect(0, h * 0.78, w, h * 0.22);

    const vig = ctx.createRadialGradient(w * 0.5, h * 0.52, Math.min(w, h) * 0.32, w * 0.5, h * 0.5, Math.max(w, h) * 0.72);
    vig.addColorStop(0, 'rgba(0,0,0,0)');
    vig.addColorStop(1, 'rgba(0,0,0,0.4)');
    ctx.fillStyle = vig;
    ctx.fillRect(0, 0, w, h);

    if (game.screenFlash > 0.01) {
      ctx.fillStyle = hexA(game.flashColor || '#ffffff', Math.min(0.7, game.screenFlash));
      ctx.fillRect(0, 0, w, h);
    }
  }

  drawOffscreenMarkers(ctx, game, originX, originY, scale) {
    if (game.phase === 'ended') return;
    const { w, h } = this.view;
    for (const f of game.fighters) {
      if (!f.alive || f.koTimer > 0) continue;
      const sx = originX + (f.x - game.camera.x) * scale;
      const sy = originY + (f.y - 55 - game.camera.y) * scale;
      if (sx > 30 && sx < w - 30 && sy > 60 && sy < h - 30) continue;
      const cx = clamp(sx, 34, w - 34);
      const cy = clamp(sy, 70, h - 40);
      const ang = Math.atan2(sy - h / 2, sx - w / 2);
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(ang + Math.PI / 2);
      ctx.fillStyle = f.color;
      ctx.shadowColor = f.color;
      ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.moveTo(0, -10);
      ctx.lineTo(7, 5);
      ctx.lineTo(-7, 5);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      ctx.save();
      ctx.fillStyle = f.color;
      ctx.font = '800 9px "Segoe UI", system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(f.tag, cx, cy + 18);
      ctx.restore();
    }
  }

  drawAnnouncement(ctx, game, time) {
    const a = game.announcement;
    if (!a) return;
    const { w, h } = this.view;
    const t = a.life / a.maxLife;
    const age = a.maxLife - a.life;
    const intro = clamp(age / 8, 0, 1);
    const scale = (1.3 - 0.3 * intro) * (1 + Math.sin(time * 0.006) * 0.012);
    const alpha = Math.min(1, a.life / 9) * Math.min(1, age / 3 + 0.2);
    const isBig = a.text === 'GAME!' || a.text === 'KO!';
    const size = Math.min(h * (isBig ? 0.16 : 0.13), w * 0.21);
    ctx.save();
    ctx.translate(w / 2, h * 0.36);
    ctx.scale(scale, scale);
    ctx.globalAlpha = alpha;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `900 ${Math.round(size)}px "Arial Black", Impact, sans-serif`;
    ctx.lineJoin = 'round';
    ctx.lineWidth = size * 0.09;
    ctx.strokeStyle = 'rgba(10,5,16,0.9)';
    ctx.strokeText(a.text, 0, 0);
    const g = ctx.createLinearGradient(0, -size * 0.5, 0, size * 0.5);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.55, a.color || '#fff');
    g.addColorStop(1, mix(a.color || '#ff7a3d', '#4a1438', 0.55));
    ctx.fillStyle = g;
    ctx.fillText(a.text, 0, 0);
    // shine sweep
    ctx.globalAlpha = alpha * 0.22;
    ctx.fillStyle = '#ffffff';
    ctx.save();
    ctx.beginPath();
    ctx.rect(-size * 3, -size * 0.35, size * 6, size * 0.14);
    ctx.clip();
    ctx.fillText(a.text, 0, 0);
    ctx.restore();

    if (a.sub) {
      ctx.globalAlpha = alpha;
      ctx.font = `800 ${Math.max(11, Math.round(size * 0.17))}px "Segoe UI", system-ui, sans-serif`;
      ctx.lineWidth = 4;
      ctx.strokeStyle = 'rgba(10,5,16,0.82)';
      ctx.strokeText(a.sub, 0, size * 0.7);
      ctx.fillStyle = 'rgba(255,255,255,0.88)';
      ctx.fillText(a.sub, 0, size * 0.7);
    }
    ctx.restore();
  }

  drawResultsBackdrop(ctx) {
    const { w, h } = this.view;
    ctx.fillStyle = 'rgba(5,4,10,0.3)';
    ctx.fillRect(0, 0, w, h);
  }
}

// ---------------------------------------------------------------------------
// SMASH ARENA — app shell, menu flow, HUD and loop.
// ---------------------------------------------------------------------------
import {
  CHARACTERS, CHAR_MAP, STAGES, SLOT_COLORS, SLOT_NAMES, DIFFICULTIES,
  defaultConfig,
} from './data.js';
import { audio } from './audio.js';
import { InputManager } from './input.js';
import { Game } from './game.js';
import { Renderer } from './renderer.js';
import { drawCharacterCard, drawAvatar } from './figure.js';
import { drawStageThumb } from './backdrop.js';

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));
const clone = (v) => JSON.parse(JSON.stringify(v));

class App {
  constructor() {
    this.config = defaultConfig();
    this.battleConfig = null;
    this.activeSlot = 0;
    this.screen = 'title';
    this.paused = false;
    this.audioReady = false;
    this.toastTimer = 0;
    this.avatarCache = new Map();
    this.lastFrame = performance.now();
    this.acc = 0;
    this.lastHud = null;
    this.cards = new Map();

    this.canvas = $('#game');
    this.renderer = new Renderer(this.canvas);
    this.input = new InputManager();
    this.game = new Game();

    this.els = {
      hud: $('#hud'),
      screenLayer: $('#screenLayer'),
      title: $('#titleScreen'),
      select: $('#selectScreen'),
      stage: $('#stageScreen'),
      results: $('#resultsScreen'),
      pause: $('#pauseModal'),
      howto: $('#howToModal'),
      toast: $('#toast'),
      charGrid: $('#charGrid'),
      slotList: $('#slotList'),
      stageGrid: $('#stageGrid'),
      stageBlurb: $('#stageBlurb'),
      resultTable: $('#resultTable'),
      resultTitle: $('#resultTitle'),
      resultEyebrow: $('#resultEyebrow'),
      winnerStrip: $('#winnerStrip'),
    };
  }

  // -------------------------------------------------------------------------
  init() {
    this.renderer.resize(window.innerWidth, window.innerHeight);
    this.input.attach();

    const unlock = () => {
      audio.init();
      if (!this.audioReady) {
        this.audioReady = true;
        audio.setMusic(this.screen === 'battle' ? 'battle' : 'menu');
      }
    };
    document.addEventListener('pointerdown', unlock, { once: false });
    document.addEventListener('keydown', unlock, { once: false });

    try {
      const saved = localStorage.getItem('smash-arena-sound');
      if (saved === 'off') audio.enabled = false;
    } catch { /* ignore */ }
    this.syncSound();

    this.bindEvents();
    this.renderer.resize(window.innerWidth, window.innerHeight);
    window.addEventListener('resize', () => {
      this.renderer.resize(window.innerWidth, window.innerHeight);
    });
    window.addEventListener('orientationchange', () => {
      setTimeout(() => this.renderer.resize(window.innerWidth, window.innerHeight), 120);
    });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.screen === 'battle' && !this.paused) this.setPaused(true);
    });
    window.addEventListener('gamepadconnected', (e) => {
      this.input.poll();
      this.toast(`GAMEPAD CONNECTED · P${(e.gamepad.index || 0) + 1}`, 2600);
    });

    this.showScreen('title');
    requestAnimationFrame((t) => this.frame(t));
  }

  bindEvents() {
    $('#quickPlay').addEventListener('click', () => {
      audio.init(); audio.click();
      const cfg = defaultConfig();
      cfg.stage = 'sky';
      this.startBattle(cfg);
    });
    $('#customPlay').addEventListener('click', () => {
      audio.init(); audio.click();
      this.openSelect();
    });
    $('#howToPlay').addEventListener('click', () => {
      audio.click();
      this.openHowTo();
    });
    $('#selectBack').addEventListener('click', () => { audio.click(); this.showScreen('title'); });
    $('#stageBack').addEventListener('click', () => { audio.click(); this.openSelect(); });
    $('#toStage').addEventListener('click', () => {
      audio.click();
      this.ensureValidLineup();
      this.openStage();
    });
    $('#startFight').addEventListener('click', () => {
      audio.click();
      this.ensureValidLineup();
      this.startBattle(clone(this.config));
    });
    $('#rematch').addEventListener('click', () => {
      audio.click();
      this.startBattle(clone(this.battleConfig || this.config));
    });
    $('#resultsCustom').addEventListener('click', () => {
      audio.click();
      if (this.battleConfig) this.config = clone(this.battleConfig);
      this.openSelect();
    });
    $('#resultsTitle').addEventListener('click', () => { audio.click(); this.showScreen('title'); });
    $('#resumeBtn').addEventListener('click', () => { audio.click(); this.setPaused(false); });
    $('#restartBtn').addEventListener('click', () => {
      audio.click();
      this.setPaused(false);
      this.startBattle(clone(this.battleConfig || this.config));
    });
    $('#pauseControlsBtn').addEventListener('click', () => { audio.click(); this.openHowTo(); });
    $('#quitBtn').addEventListener('click', () => {
      audio.click();
      this.setPaused(false);
      this.showScreen('title');
    });
    $('#howToClose').addEventListener('click', () => { audio.click(); this.closeHowTo(); });
    $('#soundBtn').addEventListener('click', () => {
      audio.init();
      audio.enabled = !audio.enabled;
      audio.setEnabled(audio.enabled);
      if (audio.enabled) { audio.setMusic(this.screen === 'battle' ? 'battle' : 'menu'); audio.click(); }
      try { localStorage.setItem('smash-arena-sound', audio.enabled ? 'on' : 'off'); } catch { /* ignore */ }
      this.syncSound();
      this.toast(audio.enabled ? 'SOUND ON' : 'SOUND OFF', 1400);
    });
    $('#fullscreenBtn').addEventListener('click', () => {
      audio.click();
      const el = document.documentElement;
      if (!document.fullscreenElement) {
        el.requestFullscreen?.().catch(() => this.toast('FULLSCREEN UNAVAILABLE', 1800));
      } else {
        document.exitFullscreen?.();
      }
    });

    // Character grid
    this.els.charGrid.addEventListener('click', (e) => {
      const card = e.target.closest('[data-char]');
      if (!card) return;
      const id = card.dataset.char;
      const slot = this.config.slots[this.activeSlot];
      if (!slot) return;
      if (slot.type === 'off') slot.type = this.activeSlot === 0 ? 'human' : 'cpu';
      slot.char = id;
      audio.click();
      this.renderSelect();
      this.advanceActiveSlot();
      this.renderSlots();
    });
    this.els.slotList.addEventListener('click', (e) => {
      const typeBtn = e.target.closest('[data-type]');
      const prev = e.target.closest('[data-prev]');
      const next = e.target.closest('[data-next]');
      const row = e.target.closest('[data-slot]');
      if (typeBtn) {
        const i = Number(typeBtn.dataset.type);
        const slot = this.config.slots[i];
        slot.type = slot.type === 'human' ? 'cpu' : slot.type === 'cpu' ? 'off' : 'human';
        this.activeSlot = i;
        if (slot.type !== 'off' && !CHAR_MAP[slot.char]) slot.char = 'blaze';
        audio.click();
        this.renderSelect();
        return;
      }
      if (prev || next) {
        const i = Number((prev || next).dataset.prev || (prev || next).dataset.next);
        const slot = this.config.slots[i];
        const idx = CHARACTERS.findIndex((c) => c.id === slot.char);
        const delta = next ? 1 : -1;
        slot.char = CHARACTERS[(idx + delta + CHARACTERS.length) % CHARACTERS.length].id;
        if (slot.type === 'off') slot.type = i === 0 ? 'human' : 'cpu';
        this.activeSlot = i;
        audio.hover();
        this.renderSelect();
        return;
      }
      if (row) {
        this.activeSlot = Number(row.dataset.slot);
        audio.hover();
        this.renderSlots();
        this.renderSelect(true);
      }
    });

    // CPU picker
    $('#cpuLevelPicker').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-level]');
      if (!btn) return;
      this.config.difficulty = Number(btn.dataset.level);
      audio.click();
      this.syncSegments();
      this.renderSlots();
    });

    // Stocks
    $('#stockPicker').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-stocks]');
      if (!btn) return;
      this.config.stocks = Number(btn.dataset.stocks);
      audio.click();
      this.syncSegments();
      this.renderStageScreen(true);
    });

    // Stages
    this.els.stageGrid.addEventListener('click', (e) => {
      const card = e.target.closest('[data-stage]');
      if (!card) return;
      this.config.stage = card.dataset.stage;
      audio.click();
      this.renderStageScreen();
    });

    // Global keys
    document.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      if (e.code === 'Escape') {
        if (!this.els.howto.classList.contains('hidden')) { this.closeHowTo(); e.preventDefault(); return; }
        if (this.screen === 'battle') { this.setPaused(!this.paused); e.preventDefault(); return; }
        if (this.screen === 'results') { this.showScreen('title'); e.preventDefault(); return; }
        if (this.screen === 'stage') { this.openSelect(); e.preventDefault(); return; }
        if (this.screen === 'select') { this.showScreen('title'); e.preventDefault(); return; }
      }
      if (e.code === 'Enter' && this.screen === 'title' && !(e.target instanceof HTMLButtonElement)) {
        $('#quickPlay').click();
      }
    });
  }

  syncSound() {
    const btn = $('#soundBtn');
    if (!btn) return;
    btn.classList.toggle('off', !audio.enabled);
    btn.innerHTML = `SOUND <b>${audio.enabled ? 'ON' : 'OFF'}</b>`;
    btn.setAttribute('aria-label', audio.enabled ? 'Mute audio' : 'Enable audio');
  }

  syncSegments() {
    $$('#cpuLevelPicker [data-level]').forEach((b) => b.classList.toggle('on', Number(b.dataset.level) === this.config.difficulty));
    $$('#stockPicker [data-stocks]').forEach((b) => b.classList.toggle('on', Number(b.dataset.stocks) === this.config.stocks));
  }

  toast(message, ms = 2200) {
    const el = this.els.toast;
    if (!el) return;
    el.textContent = message;
    el.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => el.classList.remove('show'), ms);
  }

  // -------------------------------------------------------------------------
  showScreen(name) {
    this.screen = name;
    this.input.releaseAll();
    this.els.title.classList.toggle('hidden', name !== 'title');
    this.els.select.classList.toggle('hidden', name !== 'select');
    this.els.stage.classList.toggle('hidden', name !== 'stage');
    this.els.results.classList.toggle('hidden', name !== 'results');
    this.els.hud.classList.toggle('active', name === 'battle');
    if (name !== 'battle') {
      this.els.pause.classList.add('hidden');
      this.els.howto.classList.add('hidden');
    }
    if (name === 'title') {
      this.paused = false;
      this.cards.clear();
      this.els.hud.innerHTML = '';
      audio.setMusic('menu');
    } else if (name === 'select') {
      audio.setMusic('menu');
      this.renderSelect();
    } else if (name === 'stage') {
      audio.setMusic('menu');
      this.renderStageScreen();
    } else if (name === 'battle') {
      audio.setMusic('battle');
    } else if (name === 'results') {
      audio.setMusic('menu');
    }
  }

  // -------------------------------------------------------------------------
  openSelect() {
    this.config = clone(this.config);
    if (!this.config.slots.some((s) => s.type !== 'off')) {
      this.config.slots[0] = { type: 'human', char: this.config.slots[0]?.char || 'blaze' };
    }
    this.activeSlot = Math.max(0, this.config.slots.findIndex((s) => s.type !== 'off'));
    this.showScreen('select');
    this.renderSelect();
    this.syncSegments();
  }

  openStage() {
    this.showScreen('stage');
    this.renderStageScreen();
    this.syncSegments();
  }

  ensureValidLineup() {
    const active = this.config.slots.filter((s) => s.type !== 'off');
    if (active.length === 0) {
      this.config.slots[0] = { type: 'human', char: 'blaze' };
      this.config.slots[1] = { type: 'cpu', char: 'volt' };
      this.toast('ADDED TWO FIGHTERS', 1800);
    } else if (active.length === 1) {
      const free = this.config.slots.find((s) => s.type === 'off');
      if (free) {
        free.type = 'cpu';
        free.char = free.char || 'volt';
        this.toast('RIVAL ADDED · CPU', 1600);
      }
    }
    for (const slot of this.config.slots) {
      if (slot.type !== 'off' && !CHAR_MAP[slot.char]) slot.char = 'blaze';
    }
  }

  advanceActiveSlot() {
    const slots = this.config.slots;
    for (let step = 1; step <= slots.length; step++) {
      const i = (this.activeSlot + step) % slots.length;
      if (slots[i].type !== 'off') {
        this.activeSlot = i;
        this.renderSlots();
        return;
      }
    }
    this.renderSlots();
  }

  setActiveSlot(i) {
    this.activeSlot = i;
    this.renderSlots();
  }

  // -------------------------------------------------------------------------
  renderSelect(soft = false) {
    const grid = this.els.charGrid;
    if (!grid) return;
    grid.innerHTML = CHARACTERS.map((c) => {
      const assigned = this.config.slots
        .map((s, i) => ({ ...s, i }))
        .filter((s) => s.type !== 'off' && s.char === c.id)
        .map((s) => `<span>${SLOT_NAMES[s.i]}</span>`)
        .join('');
      const active = this.config.slots.some((s) => s.type !== 'off' && s.char === c.id);
      return `
      <button class="char-card ${active ? 'selected' : ''}" data-char="${c.id}" style="--accent:${c.palette.ui[0]};--accent2:${c.palette.ui[1]}" aria-label="Select ${c.name}">
        <div class="portrait">
          <span class="slotbadge">${c.num}</span>
          <canvas data-preview="${c.id}"></canvas>
        </div>
        <div class="info">
          <div class="idx">FIGHTER ${c.num}</div>
          <h3 class="cname">${c.name}</h3>
          <p class="ctitle">${c.title}</p>
          <div class="stat-bars">
            ${this.statBar('POWER', c.stats.power, c)}
            ${this.statBar('SPEED', c.stats.speed, c)}
            ${this.statBar('WEIGHT', c.stats.weight, c)}
          </div>
          <div class="specialline">SPECIAL · <b>${c.specialName}</b></div>
        </div>
        <div class="assigned">${assigned}</div>
      </button>`;
    }).join('');
    requestAnimationFrame(() => {
      $$('canvas[data-preview]').forEach((cv) => drawCharacterCard(cv, cv.dataset.preview));
    });
    this.renderSlots();
    this.syncSegments();
  }

  statBar(label, value, c) {
    return `<div class="statline"><span>${label}</span><span class="track"><i style="width:${value * 10}%;--accent:${c.palette.ui[0]};--accent2:${c.palette.ui[1]}"></i></span></div>`;
  }

  renderSlots() {
    if (!this.els.slotList) return;
    this.els.slotList.innerHTML = this.config.slots.map((slot, i) => {
      const char = CHAR_MAP[slot.char] || CHARACTERS[0];
      const typeLabel = slot.type === 'human' ? 'YOU' : slot.type === 'cpu' ? 'CPU' : 'OFF';
      const sub = slot.type === 'off' ? 'EMPTY SLOT' : slot.type === 'human' ? 'LOCAL PLAYER' : `CPU · ${DIFFICULTIES.find((d) => d.id === this.config.difficulty)?.label || 'NORMAL'}`;
      return `
      <div class="slot-row ${i === this.activeSlot ? 'active' : ''} ${slot.type === 'off' ? 'off' : ''}" data-slot="${i}" style="--accent:${SLOT_COLORS[i]}">
        <div class="slot-avatar"><canvas data-slot-avatar="${i}"></canvas></div>
        <div class="slot-meta">
          <div class="slot-tag">${SLOT_NAMES[i]} <span style="opacity:.65">·</span> ${sub}</div>
          <div class="slot-char">${slot.type === 'off' ? '—' : char.name}</div>
        </div>
        <div class="slot-controls">
          <button class="mini-btn" data-prev="${i}" aria-label="Previous fighter for ${SLOT_NAMES[i]}">‹</button>
          <button class="type-toggle ${slot.type}" data-type="${i}" aria-label="Toggle player type for ${SLOT_NAMES[i]}">${typeLabel}</button>
          <button class="mini-btn" data-next="${i}" aria-label="Next fighter for ${SLOT_NAMES[i]}">›</button>
        </div>
      </div>`;
    }).join('');
    requestAnimationFrame(() => {
      $$('canvas[data-slot-avatar]').forEach((cv) => {
        const i = Number(cv.dataset.slotAvatar);
        const slot = this.config.slots[i];
        if (slot.type === 'off') return;
        drawAvatar(cv, slot.char);
      });
    });
  }

  // -------------------------------------------------------------------------
  openStage() {
    this.ensureValidLineup();
    this.showScreen('stage');
    this.renderStageScreen();
    this.syncSegments();
  }

  renderStageScreen(soft = false) {
    const grid = this.els.stageGrid;
    if (!grid) return;
    grid.innerHTML = STAGES.map((s) => `
      <button class="stage-card ${this.config.stage === s.id ? 'selected' : ''}" data-stage="${s.id}" style="--accent:${s.accent}" aria-label="Choose ${s.name}">
        <div class="stage-thumb">
          <canvas data-stage-thumb="${s.id}"></canvas>
          <span class="tag">${s.tag}</span>
          <span class="pick-mark">✓</span>
        </div>
        <div class="stage-info">
          <h3>${s.name}</h3>
          <p>${s.desc}</p>
        </div>
      </button>`).join('');
    requestAnimationFrame(() => {
      $$('canvas[data-stage-thumb]').forEach((cv) => drawStageThumb(cv, cv.dataset.stageThumb));
    });
    const stage = STAGES.find((s) => s.id === this.config.stage) || STAGES[0];
    if (this.els.stageBlurb) {
      this.els.stageBlurb.innerHTML = `<b>${stage.name}</b><span>${stage.short} · ${this.config.stocks} stock${this.config.stocks > 1 ? 's' : ''} · CPU ${DIFFICULTIES.find((d) => d.id === this.config.difficulty)?.label || 'NORMAL'}</span>`;
    }
    this.syncSegments();
  }

  // -------------------------------------------------------------------------
  startBattle(config) {
    this.ensureValidLineup();
    this.config = clone(config);
    this.battleConfig = clone(config);
    if (!this.config.slots.some((s) => s.type === 'human')) {
      // always give the first slot to the player if every slot is CPU
      this.config.slots[0].type = 'human';
    }
    this.paused = false;
    this.els.pause.classList.add('hidden');
    this.els.howto.classList.add('hidden');
    this.showScreen('battle');
    this.game.start(this.config, (results) => this.showResults(results));
    this.buildHud();
    this.lastHud = null;
    audio.init();
    audio.setMusic('battle');
    const human = this.config.slots
      .map((s, i) => (s.type === 'human' ? (i === 0 ? 'P1 WASD + F/G/H/SHIFT' : i === 1 ? 'P2 ARROWS + , . / \'' : `P${i + 1} READY`) : null))
      .filter(Boolean)
      .join(' · ');
    this.toast(human || 'SPECTATOR MODE', 3200);
  }

  // -------------------------------------------------------------------------
  avatarURL(charId) {
    if (this.avatarCache.has(charId)) return this.avatarCache.get(charId);
    const c = document.createElement('canvas');
    c.width = 80; c.height = 80;
    drawAvatar(c, charId);
    const url = c.toDataURL('image/png');
    this.avatarCache.set(charId, url);
    return url;
  }

  buildHud() {
    const hud = this.els.hud;
    const fighters = this.game.fighters;
    const cards = fighters.map((f) => `
      <div class="hud-card" data-slot="${f.slot}" style="--accent:${f.color}">
        <div class="hud-portrait"><img src="${this.avatarURL(f.charId)}" alt="" /></div>
        <div class="hud-ident">
          <div class="hud-player">${f.tag} <span class="tag">${f.kind === 'cpu' ? `CPU ${DIFFICULTIES.find((d) => d.id === f.difficulty)?.label || ''}` : 'YOU'}</span></div>
          <div class="hud-name">${f.char.name}</div>
          <div class="hud-stocks">${'<span class="stock-pip"></span>'.repeat(this.config.stocks)}</div>
        </div>
        <div class="hud-dmg">0<small>%</small></div>
        <div class="hud-shield"><i></i></div>
      </div>`).join('');
    hud.innerHTML = `
      <div class="hud-topline"><span class="dot"></span>${this.game.stage.name} <span class="dot"></span> STOCK <span class="dot"></span> <span class="time">0:00</span></div>
      <div class="hud-cards">${cards}</div>
      <div class="hud-tagline"><span>ESC PAUSE</span><span>${fighters.length} FIGHTERS</span></div>`;
    this.cards.clear();
    for (const f of fighters) {
      const root = hud.querySelector(`.hud-card[data-slot="${f.slot}"]`);
      this.cards.set(f.slot, {
        root,
        dmg: root.querySelector('.hud-dmg'),
        stocks: Array.from(root.querySelectorAll('.stock-pip')),
        shield: root.querySelector('.hud-shield i'),
        time: hud.querySelector('.time'),
        lastStocks: f.stocks,
        lastDamage: -1,
      });
    }
    this.lastHud = hud.querySelector('.time');
  }

  updateHud() {
    if (!this.cards.size) return;
    for (const f of this.game.fighters) {
      const c = this.cards.get(f.slot);
      if (!c) continue;
      const rounded = Math.round(f.damage);
      if (rounded !== c.lastDamage) {
        c.dmg.innerHTML = `${rounded}<small>%</small>`;
        c.root.classList.toggle('low', rounded >= 50 && rounded < 100);
        c.root.classList.toggle('mid', rounded >= 100 && rounded < 150);
        c.root.classList.toggle('high', rounded >= 150);
        c.root.classList.toggle('danger', rounded >= 200);
        c.lastDamage = rounded;
      }
      if (f.stocks !== c.lastStocks) {
        c.stocks.forEach((pip, i) => pip.classList.toggle('lost', i >= f.stocks));
        c.root.classList.toggle('koed', f.stocks <= 0);
        c.lastStocks = f.stocks;
      }
      c.root.classList.toggle('shielding', f.action === 'shield');
      c.shield.style.transform = `scaleX(${Math.max(0, f.shieldHP) / 100})`;
      c.root.classList.toggle('koed', f.stocks <= 0 || f.eliminated);
    }
    if (this.lastHud) this.lastHud.textContent = this.game.formatTime();
  }

  // -------------------------------------------------------------------------
  showResults(results) {
    const winner = results.winner;
    const anyHuman = results.rows.some((r) => r.kind === 'human');
    let title = 'DRAW';
    if (winner) title = winner.kind === 'human' ? 'VICTORY' : anyHuman ? 'DEFEAT' : 'CPU WINS';
    this.els.resultTitle.textContent = title;
    this.els.resultEyebrow.textContent = `MATCH COMPLETE · ${Math.floor(results.duration / 60 / 60)}:${String(Math.floor(results.duration / 60) % 60).padStart(2, '0')} · ${results.stage.name}`;
    this.els.resultTable.innerHTML = results.rows.map((r) => `
      <div class="result-row ${r.placement === 1 ? 'winner' : ''}" style="--accent:${r.color}">
        <div class="place">${r.placement}</div>
        <div class="ra-avatar"><canvas data-result-avatar="${r.charId}"></canvas></div>
        <div class="ra-name">${r.charName}<small>${r.tag} · ${r.kind === 'cpu' ? 'CPU' : 'PLAYER'}</small></div>
        <div class="stat">${r.kos}<small>KOs</small></div>
        <div class="stat">${r.falls}<small>FALLS</small></div>
        <div class="stat">${Math.round(r.dealt)}<small>DAMAGE</small></div>
      </div>`).join('');
    const winChar = winner ? CHAR_MAP[winner.charId] : null;
    this.els.winnerStrip.innerHTML = winner
      ? `<div class="win-avatar"><canvas data-winner-avatar="${winner.charId}"></canvas></div><span>${winner.tag} · ${winner.charName} TAKES THE ARENA</span>`
      : '<span>NO CONTEST · EVERYONE BLASTED OUT</span>';
    requestAnimationFrame(() => {
      $$('canvas[data-result-avatar]').forEach((cv) => drawAvatar(cv, cv.dataset.resultAvatar));
      const wc = document.querySelector('canvas[data-winner-avatar]');
      if (wc) drawAvatar(wc, wc.dataset.winnerAvatar);
    });
    this.paused = true;
    this.els.hud.classList.remove('active');
    this.showScreen('results');
    this.els.hud.classList.remove('active');
    if (winChar && winner.kind === 'human') audio.win();
  }

  // -------------------------------------------------------------------------
  setPaused(paused) {
    if (this.screen !== 'battle') return;
    if (paused === this.paused) return;
    this.paused = paused;
    this.els.pause.classList.toggle('hidden', !paused);
    if (paused) {
      this.input.releaseAll();
      this.els.howto.classList.add('hidden');
    } else {
      this.input.releaseAll();
      this.els.howto.classList.add('hidden');
    }
  }

  openHowTo() {
    this.els.howto.classList.remove('hidden');
    this.input.releaseAll();
  }

  closeHowTo() {
    this.els.howto.classList.add('hidden');
    audio.click();
  }

  // -------------------------------------------------------------------------
  tick() {
    this.input.poll();
    if (this.screen === 'battle') {
      if (this.input.pausePressed()) {
        this.setPaused(!this.paused);
        return;
      }
      if (this.paused) return;
      const inputs = [];
      for (const f of this.game.fighters) {
        if (f.kind === 'human') inputs[f.slot] = this.input.stateFor(f.slot);
      }
      this.game.update(inputs);
      this.updateHud();
      if (this.game.phase === 'ended') {
        // results are delivered by the game callback
      }
    }
  }

  frame(now) {
    const delta = Math.min(100, now - this.lastFrame);
    this.lastFrame = now;
    this.acc += delta;
    const step = 1000 / 60;
    let iterations = 0;
    while (this.acc >= step && iterations < 5) {
      this.tick();
      this.acc -= step;
      iterations++;
    }
    if (this.acc > step * 5) this.acc = 0;

    if (this.screen === 'battle' || this.screen === 'results') {
      this.renderer.renderGame(this.game, now);
    } else {
      this.renderer.renderMenu(this.config.stage, now, this.screen === 'title' ? 'title' : 'menu');
    }
    requestAnimationFrame((t) => this.frame(t));
  }
}

