176:   tickCountdown() {
177:     const marks = [0, 26, 52, 78];
178:     const labels = ['3', '2', '1'];
179:     if (this.countdown === marks[1] - 0) {
180:       this.announce('2', this.stage.name, '#ffffff', 22);
181:       audio.beep(false);
182:     } else if (this.countdown === marks[2]) {
183:       this.announce('1', this.stage.name, '#ffe08a', 22);
184:       audio.beep(false);
185:     } else if (this.countdown === marks[3]) {
186:       this.phase = 'fight';
187:       this.announce('GO!', '', '#b6ff5c', 34);
188:       audio.beep(true);
189:       audio.announce();
