261:   // -------------------------------------------------------------------------
262:   respawnFx(f) {
263:     this.ring(f.x, f.y - 40, f.color, 90);
264:     this.ring(f.x, f.y - 40, '#ffffff', 50);
265:     this.burst(f.x, f.y - 40, f.color, 14, 5);
266:   }
