268:   onHit(attacker, victim, dmg) {
269:     const color = attacker ? attacker.char.palette.glow : '#ffffff';
270:     const heavy = dmg > 13;
271:     this.burst(victim.x, victim.y - 44, '#fff3d0', heavy ? 14 : 8, heavy ? 7 : 4.5);
272:     this.burst(victim.x, victim.y - 44, color, heavy ? 8 : 4, 5);
273:     this.sparkArc(victim.x, victim.y - 46, Math.atan2(victim.vy, victim.vx), color, heavy);
274:     this.popup(victim.x, victim.y - 78, `${Math.ceil(dmg)}`, dmg >= 18 ? '#ff5470' : dmg >= 11 ? '#ffb347' : '#fff3d0', heavy ? 1.25 : 1);
275:     if (attacker) {
276:       const card = document.querySelector(`.hud-card[data-slot="${victim.slot}"]`);
277:       if (card) {
278:         card.classList.remove('shake');
