338:   // -------------------------------------------------------------------------
339:   updateProjectiles() {
340:     const keep = [];
341:     for (const p of this.projectiles) {
342:       p.life--;
343:       if (p.life <= 0) continue;
344:       p.vy += p.gravity;
345:       const prevY = p.y;
346:       p.x += p.vx;
347:       p.y += p.vy;
348:       p.rot = (p.rot || 0) + (p.kind === 'seed' ? 0.18 : 0.35);
349:       if (Math.random() < 0.55) {
350:         this.addParticle({
351:           type: 'trail', x: p.x, y: p.y, vx: -p.vx * 0.08, vy: -p.vy * 0.08,
352:           life: 12, maxLife: 12, size: p.r * 0.7, color: p.color, grav: 0,
353:         });
354:       }
355:       // bounce seed or projectile off the main stage surface
356:       let bounced = false;
357:       for (const plat of this.stage.platforms) {
358:         const half = plat.w / 2;
359:         if (p.x < plat.x - half || p.x > plat.x + half) continue;
360:         if (prevY <= plat.y && p.y >= plat.y && p.vy > 0) {
361:           if (p.bounce > 0) {
362:             p.y = plat.y - 1;
363:             p.vy = -Math.abs(p.vy) * 0.62;
364:             p.vx *= 0.86;
365:             p.bounce--;
366:             bounced = true;
367:             this.dust(p.x, plat.y, 0, p.color, 3);
368:             break;
369:           }
370:           if (p.kind === 'seed') {
371:             this.burst(p.x, plat.y - 8, p.color, 8, 3);
372:             p.life = 0;
373:             break;
374:           }
375:         }
376:       }
377:       if (bounced) { keep.push(p); continue; }
378:       if (p.life <= 0) continue;
379: 
380:       // bounds
381:       if (p.x < BLAST.left || p.x > BLAST.right || p.y < BLAST.top || p.y > BLAST.bottom) continue;
382: 
383:       // projectile vs projectile
384:       let clashed = false;
385:       for (const q of keep) {
386:         if (q.owner === p.owner) continue;
387:         if (Math.hypot(q.x - p.x, q.y - p.y) < q.r + p.r) {
388:           this.burst((p.x + q.x) / 2, (p.y + q.y) / 2, '#ffffff', 10, 4);
389:           this.ring((p.x + q.x) / 2, (p.y + q.y) / 2, '#8fe9ff', 24);
390:           q.life = 0;
391:           clashed = true;
392:           break;
393:         }
394:       }
395:       if (clashed) { p.life = 0; continue; }
396: 
397:       // projectile vs fighters
398:       for (const f of this.fighters) {
399:         if (f.eliminated || f.koTimer > 0 || f.slot === p.owner) continue;
400:         const box = f.hurtbox();
401:         if (circleRect(p.x, p.y, p.r, box)) {
402:           if (f.isCountering()) {
403:             const priorOwner = p.owner;
404:             p.owner = f.slot;
405:             p.vx *= -1.4;
406:             p.vy = -Math.abs(p.vy) * 0.7 - 1;
407:             p.damage *= 1.35;
408:             p.speed = Math.abs(p.vx);
409:             p.life = Math.max(40, p.life);
410:             p.color = f.char.palette.glow;
411:             this.burst(p.x, p.y, '#ffffff', 12, 6);
412:             this.onCounter(f, this.fighters.find((x) => x.slot === priorOwner));
413:             audio.counter();
414:             p.x += p.vx * 2;
415:             break;
416:           }
417:           const move = {
418:             damage: p.damage, baseKB: p.baseKB, growth: p.growth, angle: p.angle,
419:           };
420:           const owner = this.fighters.find((x) => x.slot === p.owner);
421:           const dir = Math.sign(p.vx) || 1;
422:           const res = f.takeHit(move, owner, 1, this, { dir });
423:           if (res === 'hit') {
424:             if (owner) owner.stats.dealt += p.damage;
425:             this.hitstop = Math.max(this.hitstop, 3);
426:             this.onHit(owner, f, p.damage);
427:           } else if (res === 'shield') {
428:             this.onShieldHit(owner, f);
429:             this.hitstop = Math.max(this.hitstop, 2);
430:           } else if (res === 'countered') {
431:             this.hitstop = Math.max(this.hitstop, 5);
432:           }
433:           p.life = 0;
434:           break;
435:         }
436:       }
437:       if (p.life > 0) keep.push(p);
438:     }
439:     this.projectiles = keep;
440:   }
