import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(1000);

const measure = async (label, setup) => {
  if (setup) await page.evaluate(setup);
  await page.waitForTimeout(500);
  const result = await page.evaluate(() => new Promise((res) => {
    let n = 0; const t0 = performance.now();
    const f = () => { n++; if (performance.now() - t0 < 1500) requestAnimationFrame(f); else res(n / 1.5); };
    requestAnimationFrame(f);
  }));
  console.log(label, result.toFixed(1), 'fps');
};

await measure('baseline');
await measure('no backdrop-filter', () => {
  const s = document.createElement('style');
  s.id = 'perf-no-blur';
  s.textContent = '*{backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}';
  document.head.appendChild(s);
});
await measure('no css filters', () => {
  const s = document.createElement('style');
  s.textContent = '*{filter:none !important;box-shadow:none !important;animation:none !important;}';
  document.head.appendChild(s);
});
await measure('canvas hidden', () => { document.querySelector('#game').style.visibility = 'hidden'; });
console.log('draw timings:', await page.evaluate(() => {
  const r = window.__arena.renderer;
  const t = performance.now();
  for (let i = 0; i < 10; i++) r.renderMenu('sky', i * 16, 'title');
  const menu = (performance.now() - t) / 10;
  return { menu };
}));
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const extra = process.argv[2] === 'flags' ? ['--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding', '--disable-background-timer-throttling'] : [];
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, ...extra], timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('about:blank');
const blank = await page.evaluate(() => new Promise((res) => { let n = 0; const t0 = performance.now(); const f = () => { n++; if (performance.now() - t0 < 1500) requestAnimationFrame(f); else res(n / 1.5); }; requestAnimationFrame(f); }));
await page.setContent('<h1>hi</h1>');
const simple = await page.evaluate(() => new Promise((res) => { let n = 0; const t0 = performance.now(); const f = () => { n++; if (performance.now() - t0 < 1500) requestAnimationFrame(f); else res(n / 1.5); }; requestAnimationFrame(f); }));
console.log({ blank, simple, extra });
await browser.close();

