import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(800);
await page.click('#howToPlay');
await page.waitForTimeout(500);
console.log(JSON.stringify(await page.evaluate(() => {
  const rect = (e) => { const b = e.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), right: Math.round(b.right) }; };
  return {
    card: rect(document.querySelector('.howto-card')),
    grid: rect(document.querySelector('.howto-grid')),
    cols: Array.from(document.querySelectorAll('.howto-col')).map(rect),
    rows: Array.from(document.querySelectorAll('.howto-col')).map((col) => Array.from(col.querySelectorAll('.keyrow')).map((row) => ({ row: rect(row), label: rect(row.firstElementChild), keys: rect(row.querySelector('b')) }))),
    overflow: Array.from(document.querySelectorAll('.howto-col')).map((c) => c.scrollWidth + '/' + c.clientWidth),
    gridScroll: document.querySelector('.howto-grid').scrollWidth + '/' + document.querySelector('.howto-grid').clientWidth,
  };
}), null, 2));
await page.screenshot({ path: '/home/runner/work/Tester002/Tester002/screenshots/howto-full.png', fullPage: false });
await browser.close();
